import { Injectable, signal, computed } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Router } from '@angular/router';
import { tap } from 'rxjs/operators';
import { Observable } from 'rxjs';
import { environment } from '../../../environments/environment';
import { AuthUser, LoginResponse } from '../models/auth.model';

const TOKEN_KEY = 'sf_token';
const USER_KEY = 'sf_user';

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly currentUser = signal<AuthUser | null>(this.readStoredUser());
  readonly user = this.currentUser.asReadonly();
  readonly isAuthenticated = computed(() => !!this.currentUser() && !!this.getToken());

  constructor(
    private readonly http: HttpClient,
    private readonly router: Router
  ) {}

  login(email: string, password: string): Observable<LoginResponse> {
    return this.http
      .post<LoginResponse>(`${environment.apiUrl}/auth/login`, { email, password })
      .pipe(
        tap((response) => {
          localStorage.setItem(TOKEN_KEY, response.token);
          localStorage.setItem(USER_KEY, JSON.stringify(response.user));
          this.currentUser.set(response.user);
        })
      );
  }

  logout(): void {
    localStorage.removeItem(TOKEN_KEY);
    localStorage.removeItem(USER_KEY);
    this.currentUser.set(null);
    void this.router.navigate(['/login']);
  }

  getToken(): string | null {
    return localStorage.getItem(TOKEN_KEY);
  }

  private readStoredUser(): AuthUser | null {
    const raw = localStorage.getItem(USER_KEY);
    if (!raw) {
      return null;
    }
    try {
      return JSON.parse(raw) as AuthUser;
    } catch {
      return null;
    }
  }
}

import { Compra } from '../models/compra.model';
import { Factura } from '../models/factura.model';

export function nombreProveedorCompra(compra: Compra): string {
  const p = compra.proveedor;
  if (!p) {
    return 'Proveedor';
  }
  return p.nombre_comercial || p.razon_social || p.nombre || 'Proveedor';
}

export function compraComoFactura(doc: Compra): Factura {
  const nombre = nombreProveedorCompra(doc);
  return {
    id: doc.id,
    numero: doc.numero,
    id_cliente: doc.id_proveedor,
    fecha: doc.fecha,
    metodo_pago: doc.metodo_pago,
    condicion_venta: doc.condicion_venta,
    tipo_factura: 'factura',
    moneda: doc.moneda || 'Quetzal',
    descuento: doc.descuento,
    subtotal: doc.subtotal,
    itbis: doc.iva,
    total: doc.total,
    estado: doc.estado === 'anulada' ? 'anulada' : doc.estado === 'pendiente' ? 'pendiente' : 'cancelada',
    notas: doc.notas,
    vendedor: doc.vendedor,
    cliente: {
      id: doc.proveedor?.id || doc.id_proveedor,
      nombre,
      nit: doc.proveedor?.nit || 'N/D',
      email: doc.proveedor?.email || null,
      telefono: doc.proveedor?.telefono || null,
      direccion: doc.proveedor?.direccion || null,
    },
    items: (doc.items || []).map((linea) => ({
      id: linea.id,
      id_factura: doc.id,
      id_producto: linea.id_producto,
      descripcion: linea.descripcion,
      cantidad: linea.cantidad,
      precio_unitario: linea.precio_unitario,
      subtotal: linea.subtotal,
      producto: linea.producto,
    })),
  };
}

import { Cotizacion } from '../models/cotizacion.model';
import { Factura } from '../models/factura.model';

export function cotizacionComoFactura(doc: Cotizacion): Factura {
  return {
    id: doc.id,
    numero: doc.numero,
    id_cliente: doc.id_cliente,
    fecha: doc.fecha,
    metodo_pago: doc.metodo_pago === 'credito' ? 'transferencia' : 'efectivo',
    condicion_venta: doc.metodo_pago,
    tipo_factura: 'factura',
    moneda: 'Quetzal',
    descuento: 0,
    subtotal: doc.subtotal,
    itbis: doc.itbis,
    total: doc.total,
    estado: doc.estado === 'anulada' ? 'anulada' : doc.estado === 'pendiente' ? 'pendiente' : 'cancelada',
    cliente: doc.cliente,
    items: (doc.items || []).map((linea) => ({
      id: linea.id,
      id_factura: doc.id,
      id_producto: linea.id_producto,
      descripcion: linea.descripcion,
      cantidad: linea.cantidad,
      precio_unitario: linea.precio_unitario,
      subtotal: linea.subtotal,
      producto: linea.producto,
    })),
  };
}

import { Factura } from '../models/factura.model';
import { formatGtq, money, montoEnLetras, padDoc } from './money-letras';
import {
  EmisorDte,
  condicionLabel,
  metodoPagoLabel,
  tipoFacturaLabel,
} from './factura-print';

const LETTER_W = 612;
const LETTER_H = 792;

function winAnsi(text: string): string {
  const map: Record<string, number> = {
    Á: 0xc1,
    É: 0xc9,
    Í: 0xcd,
    Ó: 0xd3,
    Ú: 0xda,
    Ü: 0xdc,
    Ñ: 0xd1,
    á: 0xe1,
    é: 0xe9,
    í: 0xed,
    ó: 0xf3,
    ú: 0xfa,
    ü: 0xfc,
    ñ: 0xf1,
    '¿': 0xbf,
    '¡': 0xa1,
    '°': 0xb0,
    '–': 0x96,
    '—': 0x97,
  };
  let out = '';
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === '(') {
      out += '\\(';
    } else if (ch === ')') {
      out += '\\)';
    } else if (map[ch] != null) {
      out += `\\${map[ch].toString(8).padStart(3, '0')}`;
    } else if (code < 32 || code > 126) {
      out += ' ';
    } else {
      out += ch;
    }
  }
  return out;
}

function wrap(text: string, maxChars: number): string[] {
  const words = String(text || '').split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let current = '';
  for (const word of words) {
    const next = current ? `${current} ${word}` : word;
    if (next.length > maxChars && current) {
      lines.push(current);
      current = word;
    } else {
      current = next;
    }
  }
  if (current) {
    lines.push(current);
  }
  return lines.length ? lines : [''];
}

export interface PdfDocumentoOpciones {
  titulo?: string;
  encabezado?: string;
  pie?: string;
  filename?: string;
}

export function buildFacturaPdfBytes(
  factura: Factura,
  emisor: Partial<EmisorDte> = {},
  opciones: PdfDocumentoOpciones = {}
): Uint8Array {
  const e = {
    nombre: emisor.nombre || 'FacturaAI',
    razonSocial: emisor.razonSocial || 'FacturaAI',
    nit: emisor.nit || 'N/D',
    telefono: emisor.telefono || 'N/D',
    email: emisor.email || 'N/D',
    direccion: emisor.direccion || 'Guatemala',
  };
  const cliente = factura.cliente;
  const items = factura.items || [];
  const total = money(factura.total);
  const descuento = money(factura.descuento);
  const gravable = money(factura.subtotal);
  const iva = money(factura.itbis);
  const precio = money(gravable + iva + descuento);
  const numero = padDoc(factura.id);
  const aut = factura.autorizacion || `FAC-${factura.id}`;
  const serie = factura.serie || aut.replace(/-/g, '').slice(0, 8);
  const noSat = factura.numero_dte || String(factura.id).padStart(10, '0');
  const anulada = factura.estado === 'anulada';
  const fecha = fechaPdf(factura.fecha);
  const navy = '0.118 0.227 0.373';

  const ops: string[] = [];
  const text = (x: number, y: number, size: number, value: string, font = 'F1') => {
    ops.push(`BT /${font} ${size} Tf 1 0 0 1 ${x.toFixed(2)} ${y.toFixed(2)} Tm (${winAnsi(value)}) Tj ET`);
  };
  const textRight = (x: number, y: number, size: number, value: string, font = 'F1') => {
    const w = value.length * size * 0.48;
    text(x - w, y, size, value, font);
  };
  const rect = (x: number, y: number, w: number, h: number, fill: string) => {
    ops.push(`${fill} rg ${x.toFixed(2)} ${y.toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re f 0 0 0 rg`);
  };
  const line = (x1: number, y1: number, x2: number, y2: number) => {
    ops.push(`0.58 0.64 0.72 RG 0.6 w ${x1.toFixed(2)} ${y1.toFixed(2)} m ${x2.toFixed(2)} ${y2.toFixed(2)} l S 0 0 0 RG`);
  };

  rect(36, 708, 54, 54, '0.98 0.8 0.082');
  text(40, 728, 7, wrap(e.nombre, 12)[0], 'F2');

  const titulo = opciones.titulo || tipoFacturaLabel(factura.tipo_factura);
  const encabezado = opciones.encabezado ?? 'DOCUMENTO TRIBUTARIO ELECTRONICO';
  const pie = opciones.pie ?? 'Representacion impresa de la Factura Electronica';

  text(360, 748, 9, encabezado, 'F2');
  text(360, 732, 13, `${titulo} # ${numero}`, 'F2');
  text(360, 712, 9, `Serie  ${serie}`);
  text(360, 700, 9, `No  ${noSat}`);
  text(360, 688, 9, `Fecha de Emision  ${fecha}`);
  text(360, 676, 9, `Vendedor  ${factura.vendedor || 'N/D'}`);

  text(36, 688, 9, `Forma de Pago: ${condicionLabel(factura.condicion_venta)}`, 'F2');
  text(36, 676, 9, `Metodos de Pago: ${metodoPagoLabel(factura.metodo_pago)}: ${formatGtq(total)}`);
  text(36, 664, 9, `Moneda: ${factura.moneda || 'Quetzal'}`);

  line(36, 652, 576, 652);
  text(36, 638, 10, 'Emisor', 'F2');
  text(36, 624, 9, e.nombre);
  text(36, 612, 9, `Razon Social: ${e.razonSocial}`);
  text(36, 600, 9, `NIT: ${e.nit}`);
  text(36, 588, 9, `Tel: ${e.telefono}`);
  text(36, 576, 9, `Email: ${e.email}`);
  wrap(e.direccion, 46).forEach((ln, i) => text(36, 564 - i * 11, 9, ln));

  text(320, 638, 10, 'Receptor', 'F2');
  text(320, 624, 9, cliente?.nombre || 'CONSUMIDOR FINAL');
  text(320, 612, 9, `NIT: ${cliente?.nit || '0'}`);
  text(320, 600, 9, `Tel: ${cliente?.telefono || 'N/D'}`);
  text(320, 588, 9, `Email: ${cliente?.email || 'N/D'}`);
  wrap(cliente?.direccion || 'N/D', 42).forEach((ln, i) => text(320, 576 - i * 11, 9, ln));
  line(36, 530, 576, 530);

  let y = 512;
  rect(36, y, 540, 16, navy);
  ops.push('1 1 1 rg');
  text(40, y + 4, 8, '#', 'F2');
  text(58, y + 4, 8, 'Cod', 'F2');
  text(108, y + 4, 8, 'Cant', 'F2');
  text(150, y + 4, 8, 'Detalle', 'F2');
  text(400, y + 4, 8, 'B/S', 'F2');
  text(430, y + 4, 8, 'P.Unit', 'F2');
  text(500, y + 4, 8, 'Total', 'F2');
  ops.push('0 0 0 rg');
  y -= 16;

  items.forEach((linea, i) => {
    if (y < 220) {
      return;
    }
    const sku = linea.producto?.sku || '-';
    const bs = linea.producto?.tipo === 'servicio' ? 'S' : 'B';
    const detalle = wrap(linea.descripcion, 42);
    text(40, y, 8, String(i + 1));
    text(58, y, 8, sku);
    textRight(140, y, 8, String(linea.cantidad));
    text(150, y, 8, detalle[0]);
    text(404, y, 8, bs);
    textRight(478, y, 8, formatGtq(linea.precio_unitario));
    textRight(570, y, 8, formatGtq(linea.subtotal));
    y -= 13;
    detalle.slice(1).forEach((ln) => {
      text(150, y, 8, ln);
      y -= 11;
    });
  });

  y = Math.min(y, 250);
  rect(360, y, 216, 14, navy);
  ops.push('1 1 1 rg');
  text(368, y + 3, 8, 'Detalle de Venta', 'F2');
  ops.push('0 0 0 rg');
  const rows: Array<[string, string, boolean]> = [
    ['Precio', `Q ${formatGtq(precio)}`, false],
    ['Descuento', `Q ${formatGtq(descuento)}`, false],
    ['Monto Gravable', `Q ${formatGtq(gravable)}`, false],
    ['Monto IVA', `Q ${formatGtq(iva)}`, false],
    ['Total Venta', `Q ${formatGtq(total)}`, false],
    ['Total a Pagar', `Q ${formatGtq(total)}`, true],
  ];
  rows.forEach(([label, value, pay], i) => {
    const ry = y - 16 - i * 14;
    if (pay) {
      rect(360, ry - 3, 216, 14, navy);
      ops.push('1 1 1 rg');
    }
    text(368, ry, 9, label, pay ? 'F2' : 'F1');
    textRight(568, ry, 9, value, pay ? 'F2' : 'F1');
    ops.push('0 0 0 rg');
  });

  ops.push('0.58 0.64 0.72 RG 0.7 w 36 70 320 78 re S 0 0 0 RG');
  text(44, 132, 8, 'Detalles', 'F2');
  wrap(montoEnLetras(total), 48).forEach((ln, i) => text(44, 118 - i * 10, 8, ln));
  text(44, 88, 8, factura.notas || 'Frases SAT: Sujeto a pagos trimestrales ISR');

  text(370, 132, 8, 'Consulte en SAT', 'F2');
  drawQr(ops, 390, 78, aut);

  text(36, 56, 8, `Numero de Autorizacion: ${aut}`, 'F2');
  text(36, 44, 8, `Serie SAT: ${serie}    Fecha de Certificacion: ${fecha}`);
  text(36, 32, 8, 'Datos Certificador: FacturaAI');
  text(36, 18, 7, pie);
  textRight(576, 18, 7, 'Pagina 1 de 1');

  if (anulada) {
    ops.push('q 0.86 0.22 0.22 rg 0.28 0 rg');
    ops.push('1 0 0 1 306 420 cm 0.883 -0.469 0.469 0.883 0 0 cm');
    ops.push('BT /F2 46 Tf 1 0 0 1 -118 -12 Tm (ANULADA) Tj ET Q');
  }

  const stream = ops.join('\n');
  return assemblePdf(stream);
}

function fechaPdf(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) {
    return '';
  }
  const pad = (n: number) => String(n).padStart(2, '0');
  const h = d.getHours();
  const ampm = h >= 12 ? 'PM' : 'AM';
  const h12 = h % 12 || 12;
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(h12)}:${pad(d.getMinutes())} ${ampm}`;
}

function drawQr(ops: string[], x: number, y: number, seed: string): void {
  const cells = 21;
  const size = 72;
  const cell = size / cells;
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  ops.push('0 0 0 rg');
  for (let row = 0; row < cells; row++) {
    for (let col = 0; col < cells; col++) {
      const finder = (col < 7 && row < 7) || (col >= cells - 7 && row < 7) || (col < 7 && row >= cells - 7);
      const border =
        finder &&
        (col === 0 ||
          row === 0 ||
          col === 6 ||
          row === 6 ||
          col === cells - 1 ||
          row === cells - 1 ||
          col === cells - 7 ||
          row === cells - 7);
      const core =
        (finder && col >= 2 && col <= 4 && row >= 2 && row <= 4) ||
        (finder && col >= cells - 5 && col <= cells - 3 && row >= 2 && row <= 4) ||
        (finder && col >= 2 && col <= 4 && row >= cells - 5 && row <= cells - 3);
      let on = finder ? border || core : false;
      if (!finder) {
        h = Math.imul(h ^ (col * 31 + row * 17), 16777619);
        on = (h >>> 0) % 3 !== 0;
      }
      if (on) {
        const px = x + col * cell;
        const py = y + (cells - 1 - row) * cell;
        ops.push(`${px.toFixed(2)} ${py.toFixed(2)} ${cell.toFixed(2)} ${cell.toFixed(2)} re f`);
      }
    }
  }
}

function assemblePdf(content: string): Uint8Array {
  const objects = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    `<< /Type /Pages /Kids [3 0 R] /Count 1 >>`,
    `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${LETTER_W} ${LETTER_H}] /Contents 4 0 R /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> >>`,
    `<< /Length ${content.length} >>\nstream\n${content}\nendstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>',
  ];
  let body = '%PDF-1.4\n';
  const offsets = [0];
  objects.forEach((obj, i) => {
    offsets.push(body.length);
    body += `${i + 1} 0 obj\n${obj}\nendobj\n`;
  });
  const xref = body.length;
  body += `xref\n0 ${objects.length + 1}\n`;
  body += '0000000000 65535 f \n';
  offsets.slice(1).forEach((off) => {
    body += `${String(off).padStart(10, '0')} 00000 n \n`;
  });
  body += `trailer << /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  const bytes = new Uint8Array(body.length);
  for (let i = 0; i < body.length; i++) {
    bytes[i] = body.charCodeAt(i) & 0xff;
  }
  return bytes;
}

function pdfBlob(bytes: Uint8Array): Blob {
  const copy = new ArrayBuffer(bytes.byteLength);
  new Uint8Array(copy).set(bytes);
  return new Blob([copy], { type: 'application/pdf' });
}

export function facturaPdfFilename(factura: Factura, opciones: PdfDocumentoOpciones = {}): string {
  return opciones.filename || `Factura-${padDoc(factura.id)}.pdf`;
}

export function descargarFacturaPdf(
  factura: Factura,
  emisor: Partial<EmisorDte> = {},
  opciones: PdfDocumentoOpciones = {}
): void {
  const blob = pdfBlob(buildFacturaPdfBytes(factura, emisor, opciones));
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = facturaPdfFilename(factura, opciones);
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1500);
}

export function abrirFacturaPdf(
  factura: Factura,
  emisor: Partial<EmisorDte> = {},
  opciones: PdfDocumentoOpciones = {}
): void {
  const blob = pdfBlob(buildFacturaPdfBytes(factura, emisor, opciones));
  const url = URL.createObjectURL(blob);
  window.open(url, '_blank', 'noopener,noreferrer');
}

import { Factura } from '../models/factura.model';
import { formatGtq, money, montoEnLetras, padDoc } from './money-letras';

export interface EmisorDte {
  nombre: string;
  razonSocial: string;
  nit: string;
  telefono: string;
  email: string;
  direccion: string;
}

const EMISOR_DEFAULT: EmisorDte = {
  nombre: 'FacturaAI',
  razonSocial: 'FacturaAI',
  nit: 'N/D',
  telefono: 'N/D',
  email: 'N/D',
  direccion: 'Guatemala',
};

export function tipoFacturaLabel(tipo?: string): string {
  if (tipo === 'factura_especial') {
    return 'Factura Especial';
  }
  if (tipo === 'factura_cambiaria') {
    return 'Factura Cambiaria';
  }
  if (tipo === 'recibo') {
    return 'Recibo';
  }
  return 'Factura Electrónica';
}

export function metodoPagoLabel(metodo?: string): string {
  if (metodo === 'tarjeta') {
    return 'Tarjeta';
  }
  if (metodo === 'transferencia') {
    return 'Transferencia';
  }
  return 'Efectivo';
}

export function condicionLabel(condicion?: string): string {
  return condicion === 'credito' ? 'Crédito' : 'Contado';
}

function esc(value: unknown): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function fechaLarga(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) {
    return '';
  }
  const pad = (n: number) => String(n).padStart(2, '0');
  const h = d.getHours();
  const ampm = h >= 12 ? 'PM' : 'AM';
  const h12 = h % 12 || 12;
  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()} ${pad(h12)}:${pad(d.getMinutes())} ${ampm}`;
}

function qrSvg(seed: string): string {
  const cells = 21;
  const size = 132;
  const cell = size / cells;
  let rects = '';
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  for (let y = 0; y < cells; y++) {
    for (let x = 0; x < cells; x++) {
      const finder =
        (x < 7 && y < 7) || (x >= cells - 7 && y < 7) || (x < 7 && y >= cells - 7);
      const onFinderBorder =
        finder && (x === 0 || y === 0 || x === 6 || y === 6 || x === cells - 1 || y === cells - 1 || x === cells - 7 || y === cells - 7);
      const onFinderCore =
        finder && x >= 2 && x <= 4 && y >= 2 && y <= 4
          ? true
          : finder && x >= cells - 5 && x <= cells - 3 && y >= 2 && y <= 4
            ? true
            : finder && x >= 2 && x <= 4 && y >= cells - 5 && y <= cells - 3;
      let on = false;
      if (finder) {
        on = onFinderBorder || onFinderCore;
      } else {
        h = Math.imul(h ^ (x * 31 + y * 17), 16777619);
        on = (h >>> 0) % 3 !== 0;
      }
      if (on) {
        rects += `<rect x="${(x * cell).toFixed(2)}" y="${(y * cell).toFixed(2)}" width="${cell + 0.2}" height="${cell + 0.2}" fill="#0f172a"/>`;
      }
    }
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" aria-hidden="true">${rects}</svg>`;
}

const DTE_CSS = `
  @page { size: letter; margin: 0; }
  :root { color-scheme: light; }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    min-height: 100%;
    font-family: Arial, Helvetica, sans-serif;
    color: #1e293b;
    background: #5c6570;
  }
  .stage {
    padding: 28px 20px 40px;
    display: flex;
    justify-content: center;
  }
  .dte {
    position: relative;
    width: 8.5in;
    min-height: 11in;
