export function ivaPorcentaje(factura: Factura): number {
  const gravable = money(factura.subtotal);
  const iva = money(factura.itbis);
  if (!gravable) {
    return 12;
  }
  return Math.max(0, Math.round((iva / gravable) * 100));
}

