  readonly recurrenteActivo = computed(() => this.url().includes('/recurrentes'));
  readonly egresosActivo = computed(() => this.url().includes('/egresos/'));
  readonly comprasActivo = computed(() => this.url().includes('/egresos/compras'));
  readonly gastosActivo = computed(() => this.url().includes('/egresos/gastos'));
  readonly cuentasActivo = computed(() => this.url().includes('/cuentas/'));
  readonly posActivo = computed(
    () => this.url() === '/pos' || this.url().startsWith('/pos/')
  );

  readonly menuOpen = signal<Record<MenuKey, boolean>>({
    receptores: this.receptoresActivo(),
    comprobantes: this.comprobantesActivo(),
    facturas: this.facturasActivo(),
    notas: this.notasActivo(),
    confirmaciones: this.confirmacionesActivo(),
    cotizaciones: this.cotizacionesActivo(),
    recurrente: this.recurrenteActivo(),
    egresos: this.egresosActivo(),
    compras: this.comprasActivo(),
    gastos: this.gastosActivo(),
    cuentas: this.cuentasActivo(),
    pos: this.posActivo(),
  });

  readonly inventarioLinks = [
    { path: '/inventario', label: 'Resumen', exact: true, icon: 'box' },
    { path: '/inventario/productos', label: 'Artículos / Servicios', exact: false, icon: 'tag' },
    { path: '/inventario/categorias', label: 'Categorías', exact: false, icon: 'layers' },
    { path: '/inventario/almacenes', label: 'Almacenes', exact: false, icon: 'warehouse' },
    { path: '/inventario/existencias', label: 'Existencias', exact: false, icon: 'layers' },
    { path: '/inventario/movimientos', label: 'Movimientos', exact: false, icon: 'swap' },
    { path: '/inventario/proveedores', label: 'Proveedores', exact: false, icon: 'truck' },
    { path: '/inventario/clientes', label: 'Clientes', exact: false, icon: 'users' },
  ];

  readonly modulos = [
    { path: '/pos', title: 'POS', text: 'Punto de venta y generación de facturas.' },
    { path: '/contabilidad', title: 'Contabilidad', text: 'Libros, ITBIS y cuentas por cobrar.' },
    { path: '/inventario', title: 'Inventario', text: 'Productos, stock, proveedores y clientes.' },
  ];

  readonly searchable = [
    { path: '/dashboard', title: 'Inicio', text: 'Dashboard operativo' },
    { path: '/comprobantes/facturas', title: 'Listado de Facturas', text: 'Comprobantes' },
    { path: '/comprobantes/facturas/crear', title: 'Crear factura', text: 'Comprobantes' },
    { path: '/comprobantes/notas/credito', title: 'Nota Crédito', text: 'Comprobantes' },
    { path: '/comprobantes/notas/anulacion', title: 'Nota Anulación', text: 'Comprobantes' },
    { path: '/comprobantes/notas/debito', title: 'Nota Débito', text: 'Comprobantes' },
    { path: '/cotizaciones', title: 'Listado de Cotización', text: 'Cotizaciones' },
    { path: '/cotizaciones/crear', title: 'Crear cotización', text: 'Cotizaciones' },
    { path: '/recurrentes', title: 'Recurrentes', text: 'Comprobantes' },
    { path: '/egresos/compras', title: 'Compras', text: 'Egresos' },
    { path: '/egresos/gastos', title: 'Gastos', text: 'Egresos' },
    { path: '/anticipos', title: 'Anticipos', text: 'Comprobantes' },
    { path: '/cuentas/cobrar', title: 'Cuentas por cobrar', text: 'Cuentas' },
    { path: '/cuentas/pagar', title: 'Cuentas por pagar', text: 'Cuentas' },
    { path: '/pos', title: 'Punto de venta', text: 'POS' },
    { path: '/pos/cajas', title: 'Cajas registradoras', text: 'POS' },
    { path: '/pos/tiquetes', title: 'Listado tiquetes', text: 'POS' },
    { path: '/opciones/sat', title: 'Estado SAT', text: 'Opciones' },
    { path: '/opciones/calendario', title: 'Calendario', text: 'Opciones' },
    ...this.modulos,
    ...this.inventarioLinks.map((link) => ({ path: link.path, title: link.label, text: 'Inventario' })),
  ];

  readonly resultados = computed(() => {
    const q = this.busqueda().trim().toLowerCase();
    if (!q) {
      return [];
    }
    return this.searchable.filter(
      (item) => item.title.toLowerCase().includes(q) || item.text.toLowerCase().includes(q)
    );
  });

  ngOnInit(): void {
    this.dashboardApi.cargarAlertas().subscribe({ error: () => undefined });
    this.router.events.pipe(filter((event): event is NavigationEnd => event instanceof NavigationEnd)).subscribe((event) => {
      this.url.set(event.urlAfterRedirects);
      this.abrirMenusActivos();
    });
  }

  abierto(menu: MenuKey): boolean {
    return this.menuOpen()[menu];
  }

  toggleMenu(menu: MenuKey, event: Event): void {
    event.preventDefault();
    event.stopPropagation();
    this.menuOpen.update((state) => ({ ...state, [menu]: !state[menu] }));
  }

  private abrirMenusActivos(): void {
    this.menuOpen.update((state) => ({
      ...state,
      receptores: state.receptores || this.receptoresActivo(),
      comprobantes: state.comprobantes || this.comprobantesActivo(),
      facturas: state.facturas || this.facturasActivo(),
      notas: state.notas || this.notasActivo(),
      confirmaciones: state.confirmaciones || this.confirmacionesActivo(),
      cotizaciones: state.cotizaciones || this.cotizacionesActivo(),
      recurrente: state.recurrente || this.recurrenteActivo(),
      egresos: state.egresos || this.egresosActivo(),
      compras: state.compras || this.comprasActivo(),
      gastos: state.gastos || this.gastosActivo(),
      cuentas: state.cuentas || this.cuentasActivo(),
      pos: state.pos || this.posActivo(),
    }));
  }

  @HostListener('document:click')
  closePopovers(): void {
    this.modulosOpen.set(false);
    this.notificacionesOpen.set(false);
  }

  toggleSidebar(): void {
    if (window.innerWidth <= 900) {
      this.sidebarOpen.update((open) => !open);
      return;
    }
    this.sidebarCollapsed.update((collapsed) => {
      const next = !collapsed;
      localStorage.setItem(SIDEBAR_KEY, next ? '1' : '0');
      return next;
    });
  }

  closeSidebar(): void {
    this.sidebarOpen.set(false);
  }

  toggleModulos(event: Event): void {
    event.stopPropagation();
    this.notificacionesOpen.set(false);
    this.modulosOpen.update((open) => !open);
  }

  toggleNotificaciones(event: Event): void {
    event.stopPropagation();
    this.modulosOpen.set(false);
    this.notificacionesOpen.update((open) => !open);
  }

  irAModulo(path: string, event: Event): void {
    event.stopPropagation();
    this.modulosOpen.set(false);
    this.closeSidebar();
    void this.router.navigate([path]);
  }

  irABusqueda(path: string, event?: Event): void {
    event?.stopPropagation();
    this.busqueda.set('');
    this.closeSidebar();
    void this.router.navigate([path]);
  }

  onSearchEnter(): void {
    const first = this.resultados()[0];
    if (first) {
      this.irABusqueda(first.path);
    }
  }

  logout(): void {
    this.auth.logout();
  }
}

import { CurrencyPipe } from '@angular/common';
import { Component, HostListener, OnInit, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';
import { InventarioService } from '../../core/services/inventario.service';
import { FacturaService } from '../../core/services/factura.service';
import { CotizacionService } from '../../core/services/cotizacion.service';
import { CarritoLinea, TipoFactura } from '../../core/models/factura.model';
import { Cliente, Producto } from '../../core/models/inventario.model';
import { apiErrorMessage } from '../../core/utils/api-error';
import { UiIcon } from '../../shared/ui-icon/ui-icon';

const IVA = 0.18;

@Component({
  selector: 'app-crear-factura',
  imports: [CurrencyPipe, FormsModule, UiIcon],
  templateUrl: './crear-factura.html',
  styleUrl: './crear-factura.css',
})
export class CrearFactura implements OnInit {
  readonly auth = inject(AuthService);
  readonly inventario = inject(InventarioService);
  readonly facturas = inject(FacturaService);
  readonly cotizaciones = inject(CotizacionService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  readonly modo = signal<'factura' | 'cotizacion'>('factura');
  readonly esCotizacion = computed(() => this.modo() === 'cotizacion');
  readonly tituloDocumento = computed(() => (this.esCotizacion() ? 'Cotización' : 'Factura Electrónica'));
  readonly editandoId = signal<number | null>(null);
  readonly etiquetaAccion = computed(() => {
    if (!this.esCotizacion()) {
      return this.emitting() ? 'Procesando…' : 'Procesar Factura';
    }
    if (this.emitting()) {
      return 'Guardando…';
    }
    return this.editandoId() ? 'Actualizar cotización' : 'Guardar cotización';
  });

  readonly seccionReceptor = signal(true);
  readonly seccionProductos = signal(true);
  readonly seccionPago = signal(true);
  readonly seccionNotas = signal(false);

  readonly exportacion = signal(false);
  readonly fechaEmision = signal(this.hoy());
  readonly tipoComprobante = signal('Factura');
  readonly busquedaCliente = signal('');
  readonly clientesOpen = signal(false);
  readonly clienteId = signal<number | null>(null);
  readonly requerimientos = signal('');
  readonly canalVenta = signal('No');
  readonly moneda = signal('Quetzal');
  readonly vendedor = signal('');
  readonly condicionVenta = signal('contado');
  readonly optContacto = signal(true);
  readonly optTaller = signal(false);
  readonly optOtras = signal(false);
  readonly optCuentaAjena = signal(false);

  readonly catalogoTipo = signal<'producto' | 'servicio'>('producto');
  readonly bodegaId = signal(1);
  readonly busquedaProducto = signal('');
  readonly productosOpen = signal(false);
  readonly formProductoOpen = signal(false);
  readonly nuevoSku = signal('');
  readonly nuevoNombre = signal('');
  readonly nuevoPrecio = signal(0);

  private lineaSeq = 1;
  readonly lineas = signal<CarritoLinea[]>([
    this.lineaVacia(),
    this.lineaVacia(),
    this.lineaVacia(),
    this.lineaVacia(),
    this.lineaVacia(),
  ]);
  readonly descuento = signal(0);
  readonly formaPago = signal<string>('efectivo');
  readonly notas = signal('');
  readonly loading = signal(false);
  readonly emitting = signal(false);
  readonly errorMessage = signal('');

  readonly cliente = computed(() =>
    this.inventario.clientes().find((c) => c.id === this.clienteId()) ?? null
  );

  readonly numeroPreview = computed(() => {
    const ids = this.esCotizacion()
      ? this.cotizaciones.cotizaciones().map((f) => f.id)
      : this.facturas.facturas().map((f) => f.id);
    return (Math.max(0, ...ids) || 0) + 1;
  });

  readonly clientesFiltrados = computed(() => {
    const q = this.busquedaCliente().trim().toLowerCase();
    return this.inventario
      .clientes()
      .filter((c) => c.estado)
      .filter((c) => {
        if (!q) {
          return true;
        }
        return (
          c.nombre.toLowerCase().includes(q) ||
          c.nit.toLowerCase().includes(q) ||
          (c.email || '').toLowerCase().includes(q)
        );
      })
      .slice(0, 8);
  });

  readonly productosFiltrados = computed(() => {
    const q = this.busquedaProducto().trim().toLowerCase();
    const tipo = this.catalogoTipo();
    return this.inventario
      .productos()
      .filter((p) => p.estado)
      .filter((p) => (tipo === 'servicio' ? this.esServicio(p) : !this.esServicio(p)))
      .filter((p) => {
        if (!q) {
          return true;
        }
        return (
          p.nombre.toLowerCase().includes(q) ||
          p.sku.toLowerCase().includes(q) ||
          (p.categoria || '').toLowerCase().includes(q)
        );
      })
      .slice(0, 10);
  });

  readonly lineasValidas = computed(() => this.lineas().filter((l) => l.id_producto > 0 && l.cantidad > 0));
  readonly subtotal = computed(() =>
    this.lineasValidas().reduce((acc, linea) => acc + linea.precio * linea.cantidad, 0)
  );
  readonly descuentoMonto = computed(() => Math.min(this.subtotal(), Math.max(0, Number(this.descuento()) || 0)));
  readonly montoBruto = computed(() => Math.round((this.subtotal() - this.descuentoMonto()) * 100) / 100);
  readonly iva = computed(() => Math.round(this.montoBruto() * IVA * 100) / 100);
  readonly total = computed(() => Math.round((this.montoBruto() + this.iva()) * 100) / 100);

  ngOnInit(): void {
    const modo = this.route.snapshot.data['modo'] === 'cotizacion' ? 'cotizacion' : 'factura';
    this.modo.set(modo);
    if (modo === 'cotizacion') {
      this.tipoComprobante.set('Cotización');
      this.formaPago.set('contado');
    }
    this.vendedor.set(this.auth.user()?.nombre || 'Vendedor');
    this.loading.set(true);
    this.inventario.cargarCatalogos().subscribe({
      next: () => {
        this.loading.set(false);
        const principal =
          this.inventario.almacenes().find((item) => item.principal && item.estado) ||
          this.inventario.almacenes().find((item) => item.estado);
        if (principal) {
          this.bodegaId.set(principal.id);
        }
        this.cargarReutilizar();
      },
      error: () => this.loading.set(false),
    });
    if (modo === 'cotizacion') {
      this.cotizaciones.listar().subscribe({ error: () => undefined });
    } else {
      this.facturas.listar().subscribe({ error: () => undefined });
    }
  }

  toggle(seccion: 'receptor' | 'productos' | 'pago' | 'notas' | 'productoForm'): void {
    if (seccion === 'receptor') {
      this.seccionReceptor.update((open) => !open);
    }
    if (seccion === 'productos') {
      this.seccionProductos.update((open) => !open);
    }
    if (seccion === 'pago') {
      this.seccionPago.update((open) => !open);
    }
    if (seccion === 'notas') {
      this.seccionNotas.update((open) => !open);
    }
    if (seccion === 'productoForm') {
      this.formProductoOpen.update((open) => !open);
    }
  }

  @HostListener('document:click')
  closeSuggest(): void {
    this.clientesOpen.set(false);
    this.productosOpen.set(false);
  }

  toNumber(value: string | number): number {
    return Number(value) || 0;
  }

  esServicio(producto: Producto): boolean {
    return producto.tipo === 'servicio' || String(producto.categoria || '').toLowerCase().includes('servicio');
  }

  seleccionarCliente(cliente: Cliente, event: Event): void {
    event.stopPropagation();
    this.clienteId.set(cliente.id);
    this.busquedaCliente.set(`${cliente.nombre} · ${cliente.nit}`);
    this.clientesOpen.set(false);
  }

  agregarProducto(producto: Producto, event: Event): void {
    event.stopPropagation();
    if (!this.esCotizacion() && !this.esServicio(producto) && producto.stock_actual < 1) {
      this.errorMessage.set(`Sin stock para ${producto.nombre}.`);
      return;
    }
    this.errorMessage.set('');
    this.lineas.update((rows) => {
      const vacia = rows.find((l) => !l.id_producto);
      const existente = rows.find((l) => l.id_producto === producto.id);
      if (existente) {
        const max =
          this.esCotizacion() || this.esServicio(producto)
            ? existente.cantidad + 1
            : Math.min(existente.stock, existente.cantidad + 1);
        return rows.map((l) => (l.id_producto === producto.id ? { ...l, cantidad: max } : l));
      }
      const nueva: CarritoLinea = {
        uid: this.lineaSeq++,
        id_producto: producto.id,
        sku: producto.sku,
        nombre: producto.nombre,
        precio: Number(producto.precio_venta),
        stock: producto.stock_actual,
        cantidad: 0,
      };
      if (vacia) {
        return rows.map((l) => (l.uid === vacia.uid ? nueva : l)).concat(this.lineaVacia());
      }
      return [...rows, nueva, this.lineaVacia()];
    });
    this.busquedaProducto.set('');
    this.productosOpen.set(false);
  }

  setSku(uid: number, value: string): void {
    const sku = value.trim();
    this.lineas.update((rows) =>
      rows.map((l) => {
        if (l.uid !== uid) {
          return l;
        }
        const found = this.inventario.productos().find((p) => p.estado && p.sku.toLowerCase() === sku.toLowerCase());
        if (!found) {
          return { ...l, sku };
        }
        return {
          ...l,
          id_producto: found.id,
          sku: found.sku,
          nombre: found.nombre,
          precio: Number(found.precio_venta),
          stock: found.stock_actual,
        };
      })
    );
    this.asegurarFilaVacia();
  }

  setNombre(uid: number, value: string): void {
    const nombre = value;
    this.lineas.update((rows) =>
      rows.map((l) => {
        if (l.uid !== uid) {
          return l;
        }
        const found = this.inventario
          .productos()
          .find((p) => p.estado && p.nombre.toLowerCase() === nombre.trim().toLowerCase());
        if (!found) {
          return { ...l, nombre };
        }
        return {
          ...l,
          id_producto: found.id,
          sku: found.sku,
          nombre: found.nombre,
          precio: Number(found.precio_venta),
          stock: found.stock_actual,
        };
      })
    );
    this.asegurarFilaVacia();
  }

  setCantidad(uid: number, value: string): void {
    const cantidad = Math.max(0, Math.floor(Number(value) || 0));
    this.lineas.update((rows) =>
      rows.map((l) => {
        if (l.uid !== uid) {
          return l;
        }
        return {
          ...l,
          cantidad:
            this.esCotizacion() || l.stock <= 0 ? cantidad : Math.min(l.stock, cantidad),
        };
      })
    );
  }

  setPrecio(uid: number, value: string): void {
    const precio = Math.max(0, Number(value) || 0);
    this.lineas.update((rows) => rows.map((l) => (l.uid === uid ? { ...l, precio } : l)));
  }

  quitar(uid: number): void {
    this.lineas.update((rows) => rows.filter((l) => l.uid !== uid));
    this.asegurarFilaVacia();
  }

  crearProductoRapido(): void {
    const sku = this.nuevoSku().trim();
    const nombre = this.nuevoNombre().trim();
    const precio = Number(this.nuevoPrecio()) || 0;
    if (!sku || !nombre) {
      this.errorMessage.set('Completa código y nombre del producto.');
      return;
    }
    this.inventario
      .crearProducto({
        sku,
        nombre,
        tipo: this.catalogoTipo() === 'servicio' ? 'servicio' : 'producto',
        categoria: this.catalogoTipo() === 'servicio' ? 'Servicios' : 'General',
        unidad_medida: this.catalogoTipo() === 'servicio' ? 'unidad de servicio' : 'unidad',
        precio_venta: precio,
        costo_compra: precio,
        stock_actual: this.catalogoTipo() === 'servicio' ? 0 : 1,
        stock_minimo: 0,
        estado: true,
      })
      .subscribe({
        next: (productos) => {
          this.formProductoOpen.set(false);
          this.nuevoSku.set('');
          this.nuevoNombre.set('');
          this.nuevoPrecio.set(0);
          const creado = productos.find((p) => p.sku === sku);
          if (creado) {
            this.agregarProducto(creado, new Event('click'));
          }
        },
        error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err)),
      });
  }

  procesar(): void {
    const idCliente = this.clienteId();
    if (!idCliente) {
      this.errorMessage.set(
        this.esCotizacion()
          ? 'Selecciona un receptor para guardar la cotización.'
          : 'Selecciona un receptor para procesar la factura.'
      );
      return;
    }
    if (!this.lineasValidas().length) {
      this.errorMessage.set('Agrega al menos un producto o servicio.');
      return;
    }

    this.emitting.set(true);
    this.errorMessage.set('');
    const items = this.lineasValidas().map((l) => ({
      id_producto: l.id_producto,
      cantidad: l.cantidad,
      precio_unitario: l.precio,
    }));

    if (this.esCotizacion()) {
      const editId = this.editandoId();
      const req =
        editId != null
          ? this.cotizaciones.actualizarDocumento(editId, {
              id_cliente: idCliente,
              metodo_pago: this.formaPago() === 'credito' || this.condicionVenta() === 'credito' ? 'credito' : 'contado',
              items,
            })
          : this.cotizaciones.crear({
              id_cliente: idCliente,
              metodo_pago: this.formaPago() === 'credito' || this.condicionVenta() === 'credito' ? 'credito' : 'contado',
              items,
            });
      req.subscribe({
        next: () => {
          this.emitting.set(false);
          this.lineas.set([
            this.lineaVacia(),
            this.lineaVacia(),
            this.lineaVacia(),
            this.lineaVacia(),
            this.lineaVacia(),
          ]);
          void this.router.navigate(['/cotizaciones']);
        },
        error: (err: unknown) => {
          this.emitting.set(false);
          this.errorMessage.set(apiErrorMessage(err, 'No se pudo guardar la cotización.'));
        },
      });
      return;
    }

    this.facturas
      .crear({
        id_cliente: idCliente,
        metodo_pago: this.formaPago() as 'efectivo' | 'tarjeta' | 'transferencia',
        condicion_venta: this.condicionVenta() === 'credito' ? 'credito' : 'contado',
        tipo_factura: this.tipoPayload(),
        vendedor: this.vendedor(),
        moneda: this.moneda(),
        descuento: this.descuentoMonto(),
        notas: this.notas(),
        items,
      })
      .subscribe({
        next: () => {
          this.emitting.set(false);
          this.lineas.set([this.lineaVacia()]);
          if (!this.router.url.includes('/pos')) {
            void this.router.navigate(['/comprobantes/facturas']);
          }
        },
        error: (err: unknown) => {
          this.emitting.set(false);
          this.errorMessage.set(apiErrorMessage(err, 'No se pudo procesar la factura.'));
        },
      });
  }

  private tipoPayload(): TipoFactura {
    const label = this.tipoComprobante();
    if (label === 'Factura especial') {
      return 'factura_especial';
    }
    if (label === 'Factura cambiaria') {
      return 'factura_cambiaria';
    }
    if (label === 'Recibo') {
      return 'recibo';
    }
    return 'factura';
  }

  private cargarReutilizar(): void {
    const editar = Number(this.route.snapshot.queryParamMap.get('editar'));
    const reutilizar = Number(this.route.snapshot.queryParamMap.get('reutilizar'));
    if (this.esCotizacion()) {
      const id = editar || reutilizar;
      if (!id) {
        return;
      }
      if (editar) {
        this.editandoId.set(editar);
      }
      this.cotizaciones.obtener(id).subscribe({
        next: (doc) => this.aplicarDocumento({
          id_cliente: doc.id_cliente,
          condicion: doc.metodo_pago,
          formaPago: doc.metodo_pago === 'credito' ? 'credito' : 'efectivo',
          items: doc.items || [],
        }),
        error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo cargar la cotización.')),
      });
      return;
    }
    const id = Number(this.route.snapshot.queryParamMap.get('reutilizar'));
    if (!id) {
      return;
    }
    this.facturas.obtener(id).subscribe({
      next: (doc) => {
        this.tipoComprobante.set(this.labelTipo(doc.tipo_factura));
        this.moneda.set(doc.moneda || 'Quetzal');
        this.vendedor.set(doc.vendedor || this.auth.user()?.nombre || 'Vendedor');
        this.descuento.set(Number(doc.descuento) || 0);
        this.notas.set(doc.notas || '');
        this.aplicarDocumento({
          id_cliente: doc.id_cliente,
          condicion: doc.condicion_venta === 'credito' ? 'credito' : 'contado',
          formaPago: doc.metodo_pago,
          items: doc.items || [],
        });
      },
      error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo reutilizar la factura.')),
    });
  }

  private aplicarDocumento(doc: {
    id_cliente: number;
    condicion: string;
    formaPago: string;
    items: Array<{
      id_producto: number;
      descripcion?: string;
      cantidad: number;
      precio_unitario: number | string;
      producto?: { sku?: string };
    }>;
  }): void {
    this.clienteId.set(doc.id_cliente);
    const cliente = this.inventario.clientes().find((c) => c.id === doc.id_cliente);
    if (cliente) {
      this.busquedaCliente.set(`${cliente.nombre} · ${cliente.nit}`);
    }
    this.condicionVenta.set(doc.condicion === 'credito' ? 'credito' : 'contado');
    this.formaPago.set(doc.formaPago);
    const lineas = doc.items.map((linea) => ({
      uid: this.lineaSeq++,
      id_producto: linea.id_producto,
      sku: linea.producto?.sku || '',
      nombre: linea.descripcion || '',
      precio: Number(linea.precio_unitario) || 0,
      stock: 9999,
      cantidad: Number(linea.cantidad) || 1,
    }));
    this.lineas.set(lineas.length ? [...lineas, this.lineaVacia()] : [this.lineaVacia()]);
  }

  private labelTipo(tipo?: string): string {
    if (tipo === 'factura_especial') {
      return 'Factura especial';
    }
    if (tipo === 'factura_cambiaria') {
      return 'Factura cambiaria';
    }
    if (tipo === 'recibo') {
      return 'Recibo';
    }
    return 'Factura';
  }

  private lineaVacia(): CarritoLinea {
    return {
      uid: this.lineaSeq++,
      id_producto: 0,
      sku: '',
      nombre: '',
      precio: 0,
      stock: 0,
      cantidad: 0,
    };
  }

  private asegurarFilaVacia(): void {
    if (!this.lineas().some((l) => !l.id_producto)) {
      this.lineas.update((rows) => [...rows, this.lineaVacia()]);
    }
  }

  private hoy(): string {
    const d = new Date();
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }
}

import { DecimalPipe, DatePipe } from '@angular/common';
import { Component, OnInit, computed, inject, signal } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { FacturaService } from '../../core/services/factura.service';
import { AuthService } from '../../core/services/auth.service';
import { Factura } from '../../core/models/factura.model';
import { apiErrorMessage } from '../../core/utils/api-error';
import { clampPage, compactPages, pageRange, pageSlice } from '../../core/utils/paginate';
import {
  abrirHtml,
  buildFacturaPosHtml,
  condicionLabel,
} from '../../core/utils/factura-print';
import { abrirFacturaPdf } from '../../core/utils/factura-pdf';
import { money } from '../../core/utils/money-letras';
import { UiIcon } from '../../shared/ui-icon/ui-icon';
import { RowMenu, RowMenuItem } from '../../shared/row-menu/row-menu';

export type ComprobanteModo = 'factura' | 'nc' | 'nd' | 'anulacion';

const ACCIONES_FACTURA: RowMenuItem[] = [
  { id: 'reutilizar', label: 'Reutilizar', icon: 'copy', accent: true },
  { id: 'pdf', label: 'Ver PDF', icon: 'pdf' },
  { id: 'pos', label: 'Impresión POS', icon: 'ticket' },
  { id: 'correo', label: 'Enviar correo', icon: 'mail' },
  { id: 'archivar', label: 'Archivar', icon: 'archive' },
  { id: 'anular', label: 'Nota de anulación', icon: 'warn' },
];

@Component({
  selector: 'app-listado-comprobantes',
  imports: [DecimalPipe, DatePipe, UiIcon, RowMenu],
  templateUrl: './listado-comprobantes.html',
  styleUrls: ['../inventario/inventario-shared.css', './listado-comprobantes.css'],
})
export class ListadoComprobantes implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  readonly facturasApi = inject(FacturaService);
  readonly auth = inject(AuthService);

  readonly titulo = signal('Listado de Facturas');
  readonly subtitulo = signal('Consulta, filtra y gestiona tus documentos.');
  readonly modo = signal<ComprobanteModo>('factura');
  readonly busqueda = signal('');
  readonly filtroMetodo = signal('');
  readonly filtroEstado = signal('');
  readonly filtroTributacion = signal('');
  readonly filtroTipo = signal('');
  readonly archivado = signal(false);
  readonly pageSize = signal(10);
  readonly pagina = signal(1);
  readonly loading = signal(false);
  readonly errorMessage = signal('');
  readonly acciones = ACCIONES_FACTURA;

  readonly origen = computed(() => {
    const modo = this.modo();
    const rows = this.facturasApi.facturas();
    if (modo === 'anulacion') {
      return rows.filter((f) => f.estado === 'anulada');
    }
    if (modo === 'nc' || modo === 'nd') {
      return [] as Factura[];
    }
    return this.archivado() ? rows.filter((f) => !!f.archivado) : rows.filter((f) => !f.archivado);
  });

  readonly filtrados = computed(() => {
    const q = this.busqueda().trim().toLowerCase();
    const metodo = this.filtroMetodo();
    const estado = this.filtroEstado();
    const tributacion = this.filtroTributacion();
    const tipo = this.filtroTipo();
    return this.origen().filter((f) => {
      const matchQ =
        !q ||
        f.numero.toLowerCase().includes(q) ||
        String(f.id).includes(q) ||
        (f.cliente?.nombre || '').toLowerCase().includes(q);
      const matchMetodo = !metodo || (f.condicion_venta || 'contado') === metodo;
      const matchEstado = !estado || this.estadoFiltro(f) === estado;
      const matchTrib = !tributacion || (f.tributacion || 'desconocido') === tributacion;
      const matchTipo = !tipo || (f.tipo_factura || 'factura') === tipo;
      return matchQ && matchMetodo && matchEstado && matchTrib && matchTipo;
    });
  });

  readonly visibles = computed(() => pageSlice(this.filtrados(), this.pagina(), this.pageSize()));
  readonly paginas = computed(() => compactPages(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly rango = computed(() => pageRange(this.filtrados().length, this.pagina(), this.pageSize()));
  readonly paginaActual = computed(() => clampPage(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly ultimaPagina = computed(() =>
    Math.max(1, Math.ceil(Math.max(this.filtrados().length, 0) / this.pageSize()) || 1)
  );

  ngOnInit(): void {
    this.aplicarRuta();
    this.route.data.subscribe(() => this.aplicarRuta());
    this.cargar();
  }

  cargar(): void {
    this.loading.set(true);
    this.errorMessage.set('');
    this.facturasApi.listar().subscribe({
      next: () => this.loading.set(false),
      error: (err) => {
        this.loading.set(false);
        this.errorMessage.set(apiErrorMessage(err, 'No se pudieron cargar los comprobantes.'));
      },
    });
  }

  setBusqueda(value: string): void {
    this.busqueda.set(value);
    this.pagina.set(1);
  }

  setFiltro(campo: 'metodo' | 'estado' | 'tributacion' | 'tipo', value: string): void {
    if (campo === 'metodo') {
      this.filtroMetodo.set(value);
    }
    if (campo === 'estado') {
      this.filtroEstado.set(value);
    }
    if (campo === 'tributacion') {
      this.filtroTributacion.set(value);
    }
    if (campo === 'tipo') {
      this.filtroTipo.set(value);
    }
    this.pagina.set(1);
  }

  setPageSize(value: string): void {
    this.pageSize.set(Number(value) || 10);
    this.pagina.set(1);
  }

  toggleArchivado(): void {
    this.archivado.update((value) => !value);
    this.pagina.set(1);
  }

  ver(item: Factura): void {
    void this.router.navigate(['/comprobantes/facturas', item.id]);
  }

  onAccion(item: Factura, accion: string): void {
    if (accion === 'reutilizar') {
      void this.router.navigate(['/comprobantes/facturas/crear'], { queryParams: { reutilizar: item.id } });
      return;
    }
    if (accion === 'pdf') {
      this.conDocumento(item, (doc) => abrirFacturaPdf(doc, this.emisor()));
      return;
    }
    if (accion === 'pos') {
      this.conDocumento(item, (doc) =>
        abrirHtml(buildFacturaPosHtml(doc, this.emisor()), { print: true, width: 420, height: 900 })
      );
      return;
    }
    if (accion === 'correo') {
      this.facturasApi.actualizar(item.id, { correo_estado: 'enviado' }).subscribe({
        error: (err) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo marcar el correo.')),
      });
      const email = item.cliente?.email;
      if (email) {
        window.location.href = `mailto:${email}?subject=${encodeURIComponent(`Factura #${item.id}`)}`;
      }
      return;
    }
    if (accion === 'archivar') {
      this.facturasApi.actualizar(item.id, { archivado: true }).subscribe({
        error: (err) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo archivar.')),
      });
      return;
    }
    if (accion === 'anular') {
      if (!confirm(`¿Registrar nota de anulación para la factura #${item.id}?`)) {
        return;
      }
      this.facturasApi.actualizar(item.id, { estado: 'anulada' }).subscribe({
        error: (err) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo anular.')),
      });
    }
  }

  iniciales(nombre: string): string {
    return (nombre || 'CF')
      .split(' ')
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0])
      .join('')
      .toUpperCase();
  }

  metodoLabel(item: Factura): string {
    return condicionLabel(item.condicion_venta);
  }

  estadoFiltro(item: Factura): 'cancelada' | 'pendiente' | 'anulada' {
    if (item.estado === 'anulada') {
      return 'anulada';
    }
    if (item.estado === 'pendiente') {
      return 'pendiente';
    }
    return 'cancelada';
  }

  estadoLabel(item: Factura): string {
    const estado = this.estadoFiltro(item);
    if (estado === 'anulada') {
      return 'Anulada';
    }
    if (estado === 'pendiente') {
      return 'Pendiente';
    }
    return 'Cancelada';
  }

  tributacionLabel(item: Factura): string {
    const t = item.tributacion || 'desconocido';
    if (t === 'no_entregado') {
      return 'No entregado';
    }
    if (t === 'aceptadas') {
      return 'Aceptadas';
    }
    if (t === 'rechazadas') {
      return 'Rechazadas';
    }
    return 'Desconocido';
  }

  correoLabel(item: Factura): string {
    return item.correo_estado === 'enviado' ? 'enviado' : 'No Entregado';
  }

  saldo(item: Factura): number {
    return this.estadoFiltro(item) === 'pendiente' ? money(item.total) : 0;
  }

  private conDocumento(item: Factura, fn: (doc: Factura) => void): void {
    if (item.items?.length) {
      fn(item);
      return;
    }
    this.facturasApi.obtener(item.id).subscribe({
      next: (doc) => fn(doc),
      error: (err) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo abrir el documento.')),
    });
  }

  private emisor() {
    const user = this.auth.user();
    return {
      nombre: user?.nombre || 'FacturaAI',
      razonSocial: 'FacturaAI',
      nit: 'N/D',
      telefono: 'N/D',
      email: user?.email || 'N/D',
      direccion: 'Guatemala',
    };
  }

  private aplicarRuta(): void {
    const data = this.route.snapshot.data;
    this.titulo.set(data['titulo'] || 'Listado de Facturas');
    this.subtitulo.set(data['subtitulo'] || 'Consulta, filtra y gestiona tus documentos.');
    this.modo.set((data['modo'] || 'factura') as ComprobanteModo);
    this.pagina.set(1);
  }
}

import { Component, OnInit, computed, inject, signal } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';
import { FacturaService } from '../../core/services/factura.service';
import { Factura } from '../../core/models/factura.model';
import { apiErrorMessage } from '../../core/utils/api-error';
import {
  abrirHtml,
  buildFacturaDteHtml,
  buildFacturaPosHtml,
  condicionLabel,
  tipoFacturaLabel,
} from '../../core/utils/factura-print';
import { abrirFacturaPdf, descargarFacturaPdf } from '../../core/utils/factura-pdf';
import { padDoc } from '../../core/utils/money-letras';
import { UiIcon } from '../../shared/ui-icon/ui-icon';

type AccordionKey = 'pagos' | 'nc' | 'nd';

@Component({
  selector: 'app-seguimiento-factura',
  imports: [RouterLink, UiIcon],
  templateUrl: './seguimiento-factura.html',
  styleUrls: ['../inventario/inventario-shared.css', './seguimiento-factura.css'],
})
export class SeguimientoFactura implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly sanitizer = inject(DomSanitizer);
  readonly auth = inject(AuthService);
  readonly api = inject(FacturaService);

  readonly loading = signal(true);
  readonly errorMessage = signal('');
  readonly factura = signal<Factura | null>(null);
  readonly abierto = signal<AccordionKey | null>('pagos');
  readonly buscaPago = signal('');
  readonly buscaNc = signal('');
  readonly buscaNd = signal('');

  readonly html = computed<SafeHtml | ''>(() => {
    const doc = this.factura();
    if (!doc) {
      return '';
    }
    return this.sanitizer.bypassSecurityTrustHtml(buildFacturaDteHtml(doc, this.emisor()));
  });

  readonly tituloDoc = computed(() => {
    const doc = this.factura();
    if (!doc) {
      return 'Factura';
    }
    return `${tipoFacturaLabel(doc.tipo_factura)} # ${padDoc(doc.id)}`;
  });

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    if (!id) {
      void this.router.navigate(['/comprobantes/facturas']);
      return;
    }
    this.api.obtener(id).subscribe({
      next: (doc) => {
        this.factura.set(doc);
        this.loading.set(false);
      },
      error: (err) => {
        this.loading.set(false);
        this.errorMessage.set(apiErrorMessage(err, 'No se pudo cargar el comprobante.'));
      },
    });
  }

  toggle(key: AccordionKey): void {
    this.abierto.update((actual) => (actual === key ? null : key));
  }

  compartir(): void {
    const url = window.location.href;
    if (navigator.clipboard?.writeText) {
      void navigator.clipboard.writeText(url);
    }
  }

  reutilizar(): void {
    const doc = this.factura();
    if (!doc) {
      return;
    }
    void this.router.navigate(['/comprobantes/facturas/crear'], { queryParams: { reutilizar: doc.id } });
  }

  descargarPdf(): void {
    const doc = this.factura();
    if (doc) {
      descargarFacturaPdf(doc, this.emisor());
    }
  }

  abrirPdf(): void {
    const doc = this.factura();
    if (doc) {
      abrirFacturaPdf(doc, this.emisor());
    }
  }

  imprimirPos(): void {
    const doc = this.factura();
    if (doc) {
      abrirHtml(buildFacturaPosHtml(doc, this.emisor()), { print: true, width: 420, height: 900 });
    }
  }

  enviarCorreo(): void {
    const doc = this.factura();
    if (!doc) {
      return;
    }
    this.api.actualizar(doc.id, { correo_estado: 'enviado' }).subscribe({
      next: (actual) => this.factura.set(actual),
      error: (err) => this.errorMessage.set(apiErrorMessage(err)),
    });
    const email = doc.cliente?.email;
    if (email) {
      window.location.href = `mailto:${email}?subject=${encodeURIComponent(`Factura #${doc.id}`)}`;
    }
  }

  anular(): void {
    const doc = this.factura();
    if (!doc || !confirm('¿Aplicar nota de anulación a este comprobante?')) {
      return;
    }
    this.api.actualizar(doc.id, { estado: 'anulada' }).subscribe({
      next: (actual) => this.factura.set(actual),
      error: (err) => this.errorMessage.set(apiErrorMessage(err)),
    });
  }

  pasoGeneracion(): string {
    const doc = this.factura();
    return doc ? new Date(doc.fecha).toLocaleDateString('es-GT') : '';
  }

  pasoTributario(): string {
    const t = this.factura()?.tributacion;
    if (t === 'aceptadas') {
      return 'Aceptado por la autoridad tributaria';
    }
    if (t === 'rechazadas') {
      return 'Rechazado';
    }
    if (t === 'no_entregado') {
      return 'No entregado';
    }
    return 'No requiere validación tributaria';
  }

  pasoCorreo(): string {
    return this.factura()?.correo_estado === 'enviado' ? 'Correo enviado' : 'Revise el correo del receptor';
  }

  pasoFinal(): string {
    const estado = this.factura()?.estado;
    if (estado === 'anulada') {
      return 'Documento anulado';
    }
    if (estado === 'pendiente') {
      return 'Pendiente de completar';
    }
    return 'Documento cancelado';
  }

  condicion(): string {
    return condicionLabel(this.factura()?.condicion_venta);
  }

  private emisor() {
    const user = this.auth.user();
    return {
      nombre: user?.nombre || 'FacturaAI',
      razonSocial: 'FacturaAI',
      nit: 'N/D',
      telefono: 'N/D',
      email: user?.email || 'N/D',
      direccion: 'Guatemala',
    };
  }
}

import { DecimalPipe, DatePipe } from '@angular/common';
import { Component, OnInit, computed, inject, signal } from '@angular/core';
import { Router } from '@angular/router';
import { CotizacionService } from '../../core/services/cotizacion.service';
import { AuthService } from '../../core/services/auth.service';
import { Cotizacion } from '../../core/models/cotizacion.model';
import { apiErrorMessage } from '../../core/utils/api-error';
import { clampPage, compactPages, pageRange, pageSlice } from '../../core/utils/paginate';
import { money } from '../../core/utils/money-letras';
import { abrirHtml, buildFacturaPosHtml } from '../../core/utils/factura-print';
import { abrirFacturaPdf } from '../../core/utils/factura-pdf';
import { cotizacionComoFactura } from '../../core/utils/cotizacion-print';
import { UiIcon } from '../../shared/ui-icon/ui-icon';
import { RowMenu, RowMenuItem } from '../../shared/row-menu/row-menu';

@Component({
  selector: 'app-listado-cotizaciones',
  imports: [DecimalPipe, DatePipe, UiIcon, RowMenu],
  templateUrl: './listado-cotizaciones.html',
  styleUrls: ['../inventario/inventario-shared.css', './listado-cotizaciones.css'],
})
export class ListadoCotizaciones implements OnInit {
  readonly api = inject(CotizacionService);
  readonly auth = inject(AuthService);
  private readonly router = inject(Router);

  readonly busqueda = signal('');
  readonly filtroMetodo = signal('');
  readonly filtroEstado = signal('');
  readonly archivado = signal(false);
  readonly pageSize = signal(10);
  readonly pagina = signal(1);
  readonly loading = signal(false);
  readonly errorMessage = signal('');
  readonly generando = signal(false);
  readonly modal = signal<Cotizacion | null>(null);
  readonly fechaEmision = signal('');

  readonly origen = computed(() => {
    const rows = this.api.cotizaciones();
    return this.archivado()
      ? rows.filter((row) => row.estado === 'archivada')
      : rows.filter((row) => row.estado !== 'archivada');
  });

  readonly filtrados = computed(() => {
    const q = this.busqueda().trim().toLowerCase();
    const metodo = this.filtroMetodo();
    const estado = this.filtroEstado();
    return this.origen().filter((row) => {
      const matchQ =
        !q ||
        row.numero.toLowerCase().includes(q) ||
        String(row.id).includes(q) ||
        (row.cliente?.nombre || '').toLowerCase().includes(q);
      const matchMetodo = !metodo || row.metodo_pago === metodo;
      const matchEstado = !estado || row.estado === estado;
      return matchQ && matchMetodo && matchEstado;
    });
  });

  readonly visibles = computed(() => pageSlice(this.filtrados(), this.pagina(), this.pageSize()));
  readonly paginas = computed(() => compactPages(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly rango = computed(() => pageRange(this.filtrados().length, this.pagina(), this.pageSize()));
  readonly paginaActual = computed(() => clampPage(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly ultimaPagina = computed(() =>
    Math.max(1, Math.ceil(Math.max(this.filtrados().length, 0) / this.pageSize()) || 1)
  );

  ngOnInit(): void {
    this.cargar();
  }

  cargar(): void {
    this.loading.set(true);
    this.errorMessage.set('');
    this.api.listar().subscribe({
      next: () => this.loading.set(false),
      error: (err: unknown) => {
        this.loading.set(false);
        this.errorMessage.set(apiErrorMessage(err, 'No se pudieron cargar las cotizaciones.'));
      },
    });
  }

  setBusqueda(value: string): void {
    this.busqueda.set(value);
    this.pagina.set(1);
  }

  setFiltro(campo: 'metodo' | 'estado', value: string): void {
    if (campo === 'metodo') {
      this.filtroMetodo.set(value);
    } else {
      this.filtroEstado.set(value);
    }
    this.pagina.set(1);
  }

  setPageSize(value: string): void {
    this.pageSize.set(Number(value) || 10);
    this.pagina.set(1);
  }

  toggleArchivado(): void {
    this.archivado.update((value) => !value);
    this.pagina.set(1);
  }

  acciones(item: Cotizacion): RowMenuItem[] {
    const puedeEditar = item.estado === 'pendiente' && !item.generada;
    const items: RowMenuItem[] = [];
    if (puedeEditar) {
      items.push({ id: 'editar', label: 'Editar', icon: 'pencil' });
    }
    items.push({ id: 'reutilizar', label: 'Reutilizar', icon: 'copy', accent: true });
    if (puedeEditar) {
      items.push({ id: 'generar', label: 'Generar Factura/Ticket', icon: 'document' });
    }
    items.push(
      { id: 'pdf', label: 'Ver PDF', icon: 'pdf' },
      { id: 'pos', label: 'Impresión POS', icon: 'ticket' },
      { id: 'correo', label: 'Enviar correo', icon: 'mail' }
    );
    if (item.estado !== 'archivada') {
      items.push({ id: 'archivar', label: 'Archivar', icon: 'archive' });
    }
    if (item.estado !== 'anulada' && item.estado !== 'archivada') {
      items.push({ id: 'anular', label: 'Anulación Local', icon: 'warn' });
    }
    return items;
  }

  onAccion(item: Cotizacion, accion: string): void {
    if (accion === 'editar') {
      void this.router.navigate(['/cotizaciones/crear'], { queryParams: { editar: item.id } });
      return;
    }
    if (accion === 'reutilizar') {
      void this.router.navigate(['/cotizaciones/crear'], { queryParams: { reutilizar: item.id } });
      return;
    }
    if (accion === 'generar') {
      this.abrirGenerar(item);
      return;
    }
    if (accion === 'pdf') {
      this.conDocumento(item, (doc) =>
        abrirFacturaPdf(cotizacionComoFactura(doc), this.emisor(), {
          titulo: 'Cotización',
          encabezado: 'COTIZACION',
          pie: 'Representacion impresa de la Cotizacion',
          filename: `Cotizacion-${String(doc.id).padStart(10, '0')}.pdf`,
        })
      );
      return;
    }
    if (accion === 'pos') {
      this.conDocumento(item, (doc) =>
        abrirHtml(buildFacturaPosHtml(cotizacionComoFactura(doc), this.emisor()), {
          print: true,
          width: 420,
          height: 900,
        })
      );
      return;
    }
    if (accion === 'correo') {
      const email = item.cliente?.email;
      if (email) {
        window.location.href = `mailto:${email}?subject=${encodeURIComponent(`Cotización #${item.id}`)}`;
      } else {
        this.errorMessage.set('El receptor no tiene correo registrado.');
      }
      return;
    }
    if (accion === 'archivar') {
      this.api.actualizar(item.id, { estado: 'archivada' }).subscribe({
        error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo archivar.')),
      });
      return;
    }
    if (accion === 'anular') {
      if (!confirm(`¿Registrar anulación local de la cotización #${item.id}?`)) {
        return;
      }
      this.api.actualizar(item.id, { estado: 'anulada' }).subscribe({
        error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo anular.')),
      });
    }
  }

  abrirGenerar(item: Cotizacion): void {
    if (item.generada || item.estado !== 'pendiente') {
      this.errorMessage.set('Esta cotización no se puede generar.');
      return;
    }
    this.errorMessage.set('');
    this.fechaEmision.set(this.hoyInput());
    this.conDocumento(item, (doc) => this.modal.set(doc));
  }

  cerrarModal(): void {
    this.modal.set(null);
    this.generando.set(false);
  }

  editarDesdeModal(item: Cotizacion): void {
    this.cerrarModal();
    void this.router.navigate(['/cotizaciones/crear'], { queryParams: { editar: item.id } });
  }

  generar(tipo: 'factura' | 'recibo'): void {
    const item = this.modal();
    if (!item) {
      return;
    }
    this.generando.set(true);
    this.errorMessage.set('');
    this.api
      .convertirAFactura(item.id, {
        tipo_factura: tipo,
        fecha: this.fechaEmision() || undefined,
      })
      .subscribe({
        next: () => {
          this.generando.set(false);
          this.cerrarModal();
        },
        error: (err: unknown) => {
          this.generando.set(false);
          this.errorMessage.set(apiErrorMessage(err, 'No se pudo generar el comprobante.'));
        },
      });
  }

  iniciales(nombre: string): string {
    return (nombre || 'CF')
      .split(' ')
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0])
      .join('')
      .toUpperCase();
  }

  metodoLabel(metodo: Cotizacion['metodo_pago']): string {
    return metodo === 'credito' ? 'Crédito' : 'Contado';
  }

  formaPagoLabel(item: Cotizacion): string {
    return item.metodo_pago === 'credito' ? 'Crédito' : 'Efectivo';
  }

  estadoLabel(estado: Cotizacion['estado']): string {
    if (estado === 'cancelada') {
      return 'Cancelada';
    }
    if (estado === 'anulada') {
      return 'Anulada';
    }
    if (estado === 'archivada') {
      return 'Archivada';
    }
    return 'Pendiente';
  }

  saldo(item: Cotizacion): number {
    if (item.metodo_pago === 'credito' && item.estado === 'pendiente') {
      return money(item.total);
    }
    return 0;
  }

  totalLineas(item: Cotizacion): number {
    return (item.items || []).reduce((acc, linea) => acc + money(linea.subtotal), 0);
  }

  private conDocumento(item: Cotizacion, fn: (doc: Cotizacion) => void): void {
    if (item.items?.length) {
      fn(item);
      return;
    }
    this.api.obtener(item.id).subscribe({
      next: (doc) => fn(doc),
      error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo abrir el documento.')),
    });
  }

  private hoyInput(): string {
    const d = new Date();
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  }

  private emisor() {
    const user = this.auth.user();
    return {
      nombre: user?.nombre || 'FacturaAI',
      razonSocial: 'FacturaAI',
      nit: 'N/D',
      telefono: 'N/D',
      email: user?.email || 'N/D',
      direccion: 'Guatemala',
    };
  }
}

import { DecimalPipe, DatePipe } from '@angular/common';
import { Component, OnInit, computed, inject, signal } from '@angular/core';
import { Router } from '@angular/router';
import { CompraService } from '../../core/services/compra.service';
import { AuthService } from '../../core/services/auth.service';
import { Compra } from '../../core/models/compra.model';
import { apiErrorMessage } from '../../core/utils/api-error';
import { clampPage, compactPages, pageRange, pageSlice } from '../../core/utils/paginate';
import { money } from '../../core/utils/money-letras';
import { abrirHtml, buildFacturaPosHtml } from '../../core/utils/factura-print';
import { abrirFacturaPdf } from '../../core/utils/factura-pdf';
import { compraComoFactura, nombreProveedorCompra } from '../../core/utils/compra-print';
import { UiIcon } from '../../shared/ui-icon/ui-icon';
import { RowMenu, RowMenuItem } from '../../shared/row-menu/row-menu';

const ACCIONES: RowMenuItem[] = [
  { id: 'reutilizar', label: 'Reutilizar', icon: 'copy', accent: true },
  { id: 'pdf', label: 'Ver PDF', icon: 'pdf' },
  { id: 'pos', label: 'Impresión POS', icon: 'ticket' },
  { id: 'correo', label: 'Enviar correo', icon: 'mail' },
  { id: 'archivar', label: 'Archivar', icon: 'archive' },
  { id: 'anular', label: 'Anulación Local', icon: 'warn' },
];

@Component({
  selector: 'app-listado-compras',
  imports: [DecimalPipe, DatePipe, UiIcon, RowMenu],
  templateUrl: './listado-compras.html',
  styleUrls: ['../inventario/inventario-shared.css', '../comprobantes/listado-comprobantes.css', './listado-compras.css'],
})
export class ListadoCompras implements OnInit {
  readonly api = inject(CompraService);
  readonly auth = inject(AuthService);
  private readonly router = inject(Router);

  readonly busqueda = signal('');
  readonly filtroMetodo = signal('');
  readonly filtroEstado = signal('');
  readonly archivado = signal(false);
  readonly pageSize = signal(10);
  readonly pagina = signal(1);
  readonly loading = signal(false);
  readonly errorMessage = signal('');
  readonly acciones = ACCIONES;

  readonly origen = computed(() => {
    const rows = this.api.compras();
    return this.archivado() ? rows.filter((row) => !!row.archivado) : rows.filter((row) => !row.archivado);
  });

  readonly filtrados = computed(() => {
    const q = this.busqueda().trim().toLowerCase();
    const metodo = this.filtroMetodo();
    const estado = this.filtroEstado();
    return this.origen().filter((row) => {
      const nombre = nombreProveedorCompra(row).toLowerCase();
      const matchQ =
        !q ||
        row.numero.toLowerCase().includes(q) ||
        String(row.id).includes(q) ||
        (row.numero_proveedor || '').toLowerCase().includes(q) ||
        nombre.includes(q);
      const matchMetodo = !metodo || row.condicion_venta === metodo;
      const matchEstado = !estado || this.estadoFiltro(row) === estado;
      return matchQ && matchMetodo && matchEstado;
    });
  });

  readonly visibles = computed(() => pageSlice(this.filtrados(), this.pagina(), this.pageSize()));
  readonly paginas = computed(() => compactPages(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly rango = computed(() => pageRange(this.filtrados().length, this.pagina(), this.pageSize()));
  readonly paginaActual = computed(() => clampPage(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly ultimaPagina = computed(() =>
    Math.max(1, Math.ceil(Math.max(this.filtrados().length, 0) / this.pageSize()) || 1)
  );

  ngOnInit(): void {
    this.cargar();
  }

  cargar(): void {
    this.loading.set(true);
    this.errorMessage.set('');
    this.api.listar().subscribe({
      next: () => this.loading.set(false),
      error: (err: unknown) => {
        this.loading.set(false);
        this.errorMessage.set(apiErrorMessage(err, 'No se pudieron cargar las compras.'));
      },
    });
  }

  setBusqueda(value: string): void {
    this.busqueda.set(value);
    this.pagina.set(1);
  }

  setFiltro(campo: 'metodo' | 'estado', value: string): void {
    if (campo === 'metodo') {
      this.filtroMetodo.set(value);
    } else {
      this.filtroEstado.set(value);
    }
    this.pagina.set(1);
  }

  setPageSize(value: string): void {
    this.pageSize.set(Number(value) || 10);
    this.pagina.set(1);
  }

  toggleArchivado(): void {
    this.archivado.update((value) => !value);
    this.pagina.set(1);
  }

  onAccion(item: Compra, accion: string): void {
    if (accion === 'reutilizar') {
      void this.router.navigate(['/egresos/compras/crear'], { queryParams: { reutilizar: item.id } });
      return;
    }
    if (accion === 'pdf') {
      this.conDocumento(item, (doc) =>
        abrirFacturaPdf(compraComoFactura(doc), this.emisor(), {
          titulo: 'Compra',
          encabezado: 'COMPRA',
          pie: 'Representacion impresa de la Compra',
          filename: `Compra-${String(doc.id).padStart(10, '0')}.pdf`,
        })
      );
      return;
    }
    if (accion === 'pos') {
      this.conDocumento(item, (doc) =>
        abrirHtml(buildFacturaPosHtml(compraComoFactura(doc), this.emisor()), {
          print: true,
          width: 420,
          height: 900,
        })
      );
      return;
    }
    if (accion === 'correo') {
      const email = item.proveedor?.email;
      if (email) {
        window.location.href = `mailto:${email}?subject=${encodeURIComponent(`Compra #${item.id}`)}`;
      } else {
        this.errorMessage.set('El proveedor no tiene correo registrado.');
      }
      return;
    }
    if (accion === 'archivar') {
      this.api.actualizar(item.id, { archivado: true }).subscribe({
        error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo archivar.')),
      });
      return;
    }
    if (accion === 'anular') {
      if (this.estadoFiltro(item) === 'anulada') {
        return;
      }
      if (!confirm(`¿Registrar anulación local de la compra #${item.id}? Se revertirá el inventario.`)) {
        return;
      }
      this.api.actualizar(item.id, { estado: 'anulada' }).subscribe({
        error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo anular.')),
      });
    }
  }

  accionesFila(item: Compra): RowMenuItem[] {
    return this.acciones.filter((accion) => {
      if (accion.id === 'archivar') {
        return !item.archivado;
      }
      if (accion.id === 'anular') {
        return this.estadoFiltro(item) !== 'anulada';
      }
      return true;
    });
  }

  iniciales(nombre: string): string {
    return (nombre || 'PR')
      .split(' ')
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0])
      .join('')
      .toUpperCase();
  }

  receptor(item: Compra): string {
    return nombreProveedorCompra(item);
  }

  metodoLabel(item: Compra): string {
    return item.condicion_venta === 'credito' ? 'Crédito' : 'Contado';
  }

  estadoFiltro(item: Compra): 'pendiente' | 'cancelada' | 'anulada' {
    if (item.estado === 'anulada') {
      return 'anulada';
    }
    if (item.estado === 'pendiente' || (item.estado === 'registrada' && item.condicion_venta === 'credito')) {
      return 'pendiente';
    }
    return 'cancelada';
  }

  estadoLabel(item: Compra): string {
    const estado = this.estadoFiltro(item);
    if (estado === 'anulada') {
      return 'Anulada';
    }
    if (estado === 'pendiente') {
      return 'Pendiente';
    }
    return 'Cancelada';
  }

  saldo(item: Compra): number {
    return this.estadoFiltro(item) === 'pendiente' ? money(item.total) : 0;
  }

  private conDocumento(item: Compra, fn: (doc: Compra) => void): void {
    if (item.items?.length) {
      fn(item);
      return;
    }
    this.api.obtener(item.id).subscribe({
      next: (doc) => fn(doc),
      error: (err: unknown) => this.errorMessage.set(apiErrorMessage(err, 'No se pudo abrir el documento.')),
    });
  }

  private emisor() {
    const user = this.auth.user();
    return {
      nombre: user?.nombre || 'FacturaAI',
      razonSocial: 'FacturaAI',
      nit: 'N/D',
      telefono: 'N/D',
      email: user?.email || 'N/D',
      direccion: 'Guatemala',
    };
  }
}

import { Component, HostListener, OnInit, computed, signal } from '@angular/core';
import { InventarioNav } from './inventario-nav';
import { InventarioService } from '../../core/services/inventario.service';
import { FacturaService } from '../../core/services/factura.service';
import {
  DevolucionFactura,
  DevolucionFacturaItem,
  DevolucionInventario,
  Existencia,
  RazonDevolucion,
  ResolucionDevolucion,
} from '../../core/models/inventario.model';
import { Factura } from '../../core/models/factura.model';
import { apiErrorMessage } from '../../core/utils/api-error';
import { clampPage, compactPages, pageRange, pageSlice, PageToken } from '../../core/utils/paginate';
import { UiIcon } from '../../shared/ui-icon/ui-icon';

interface LineaDevolucion extends DevolucionFacturaItem {
  cantidad_devolver: number;
  id_producto_cambio: number | null;
  cantidad_cambio: number;
  precio_cambio: number;
}

const RAZONES: Array<{ id: RazonDevolucion | ''; label: string }> = [
  { id: '', label: 'Todas' },
  { id: 'danado', label: 'Dañado' },
  { id: 'vencido', label: 'Vencido' },
  { id: 'no_gusto', label: 'No gustó' },
  { id: 'cambio_producto', label: 'Cambio producto' },
];

const RAZON_LABEL: Record<RazonDevolucion, string> = {
  danado: 'Dañado',
  vencido: 'Vencido',
  no_gusto: 'No gustó',
  cambio_producto: 'Cambio producto',
};

const RESOLUCION_LABEL: Record<ResolucionDevolucion, string> = {
  reembolso_efectivo: 'Reembolso efectivo',
  nota_credito: 'Nota de crédito',
  cambio: 'Cambio de producto',
};

const ITBIS = 0.18;

@Component({
  selector: 'app-devoluciones',
  imports: [InventarioNav, UiIcon],
  templateUrl: './devoluciones.html',
  styleUrls: ['./inventario-shared.css', './categorias.css', './ajustes.css', './traslados.css', './devoluciones.css'],
})
export class DevolucionesInventario implements OnInit {
  readonly razones = RAZONES;
  readonly razonFiltro = signal<RazonDevolucion | ''>('');
  readonly busqueda = signal('');
  readonly pagina = signal(1);
  readonly pageSize = signal(10);
  readonly loading = signal(false);
  readonly saving = signal(false);
  readonly errorMessage = signal('');

  readonly formOpen = signal(false);
  readonly detalle = signal<DevolucionInventario | null>(null);
  readonly menuId = signal<number | null>(null);

  readonly bodegaId = signal<number | null>(null);
  readonly razon = signal<RazonDevolucion>('no_gusto');
  readonly resolucion = signal<Exclude<ResolucionDevolucion, 'cambio'>>('reembolso_efectivo');
  readonly observacion = signal('');
  readonly formError = signal('');

  readonly busquedaFactura = signal('');
  readonly facturas = signal<Factura[]>([]);
  readonly factura = signal<DevolucionFactura | null>(null);
  readonly loadingFactura = signal(false);
  readonly lineas = signal<LineaDevolucion[]>([]);

  readonly catalogo = signal<Existencia[]>([]);
  readonly loadingCatalogo = signal(false);

  readonly filtrados = computed(() => {
    const q = this.busqueda().trim().toLowerCase();
    const razon = this.razonFiltro();
    return this.inventario.devoluciones().filter((item) => {
      if (razon && item.razon !== razon) {
        return false;
      }
      if (!q) {
        return true;
      }
      const productos = item.items.map((linea) => `${linea.producto} ${linea.sku}`).join(' ');
      return (
        item.numero.toLowerCase().includes(q) ||
        item.referencia_nc.toLowerCase().includes(q) ||
        item.factura.toLowerCase().includes(q) ||
        item.cliente.toLowerCase().includes(q) ||
        productos.toLowerCase().includes(q)
      );
    });
  });

  readonly visibles = computed(() => pageSlice(this.filtrados(), this.pagina(), this.pageSize()));
  readonly paginas = computed(() => compactPages(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly rango = computed(() => pageRange(this.filtrados().length, this.pagina(), this.pageSize()));
  readonly paginaActual = computed(() =>
    clampPage(this.pagina(), this.filtrados().length, this.pageSize())
  );
  readonly totalPaginas = computed(() =>
    Math.max(1, Math.ceil(Math.max(this.filtrados().length, 0) / this.pageSize()))
  );

  readonly facturasFiltradas = computed(() => {
    const q = this.busquedaFactura().trim().toLowerCase();
    return this.facturas()
      .filter((item) => item.estado === 'emitida')
      .filter((item) => {
        if (!q) {
          return true;
        }
        return (
          item.numero.toLowerCase().includes(q) ||
          (item.cliente?.nombre || '').toLowerCase().includes(q) ||
          (item.cliente?.nit || '').toLowerCase().includes(q)
        );
      })
      .slice(0, 8);
  });

  readonly esCambio = computed(() => this.razon() === 'cambio_producto');
  readonly restableceStock = computed(() => this.razon() === 'no_gusto' || this.razon() === 'cambio_producto');

  readonly resumen = computed(() => {
    const activas = this.lineas().filter((item) => item.cantidad_devolver > 0);
    const subtotal = round(activas.reduce((sum, item) => sum + item.cantidad_devolver * item.precio_unitario, 0));
    const itbis = round(subtotal * ITBIS);
    const total = round(subtotal + itbis);
    let subtotalCambio = 0;
    if (this.esCambio()) {
      subtotalCambio = round(
        activas.reduce((sum, item) => sum + item.cantidad_cambio * item.precio_cambio, 0)
      );
    }
    const itbisCambio = round(subtotalCambio * ITBIS);
    const totalCambio = round(subtotalCambio + itbisCambio);
    const diferencia = round(totalCambio - total);
    let reembolso = 0;
    let cobro = 0;
    let nota = 0;
    if (this.esCambio()) {
      if (diferencia > 0) cobro = diferencia;
      if (diferencia < 0) reembolso = round(-diferencia);
    } else if (this.resolucion() === 'reembolso_efectivo') {
      reembolso = total;
    } else {
      nota = total;
    }
    return { subtotal, itbis, total, subtotalCambio, itbisCambio, totalCambio, diferencia, reembolso, cobro, nota };
  });

  readonly puedeGuardar = computed(() => {
    if (this.saving() || !this.factura() || !this.bodegaId()) {
      return false;
    }
    const activas = this.lineas().filter((item) => item.cantidad_devolver > 0);
    if (!activas.length) {
      return false;
    }
    if (this.esCambio()) {
      return activas.every(
        (item) => item.id_producto_cambio && item.cantidad_cambio > 0 && item.precio_cambio >= 0
      );
    }
    return true;
  });

  constructor(
    readonly inventario: InventarioService,
    private readonly facturasApi: FacturaService
  ) {}

  ngOnInit(): void {
    this.cargar();
    this.inventario.listarBodegas().subscribe();
  }

  @HostListener('document:click')
  closeMenu(): void {
    this.menuId.set(null);
  }

  @HostListener('document:keydown.escape')
  onEscape(): void {
    if (this.saving()) {
      return;
    }
    if (this.detalle()) {
      this.detalle.set(null);
      return;
    }
    if (this.formOpen()) {
      this.cancelar();
    }
  }

  cargar(): void {
    this.loading.set(true);
    this.errorMessage.set('');
    this.inventario.listarDevoluciones().subscribe({
      next: () => this.loading.set(false),
      error: (err) => {
        this.loading.set(false);
        this.errorMessage.set(apiErrorMessage(err, 'No se pudieron cargar las devoluciones.'));
      },
    });
  }

  abrirNuevo(): void {
    this.formError.set('');
    this.bodegaId.set(this.inventario.almacenes().find((item) => item.principal && item.estado)?.id || null);
    this.razon.set('no_gusto');
    this.resolucion.set('reembolso_efectivo');
    this.observacion.set('');
    this.busquedaFactura.set('');
    this.factura.set(null);
    this.lineas.set([]);
    this.catalogo.set([]);
    this.formOpen.set(true);
    this.facturasApi.listar().subscribe({
      next: (rows) => this.facturas.set(rows),
      error: (err) => this.formError.set(apiErrorMessage(err, 'No se pudieron cargar las facturas.')),
    });
    if (this.bodegaId()) {
      this.cargarCatalogo(this.bodegaId()!);
    }
  }

  cancelar(): void {
    if (this.saving()) {
      return;
    }
    this.formOpen.set(false);
    this.formError.set('');
  }

  seleccionarBodega(value: string): void {
    const id = Number(value) || null;
    this.bodegaId.set(id);
    this.catalogo.set([]);
    if (id) {
      this.cargarCatalogo(id);
    }
  }

  setRazon(value: string): void {
    const razon = (value || 'no_gusto') as RazonDevolucion;
    this.razon.set(razon);
    if (razon === 'cambio_producto') {
      this.lineas.update((lista) =>
        lista.map((item) => ({
          ...item,
          cantidad_cambio: item.cantidad_cambio || item.cantidad_devolver || 1,
          precio_cambio: item.precio_cambio || item.precio_venta || item.precio_unitario,
        }))
      );
    }
  }

  setResolucion(value: string): void {
    this.resolucion.set(value === 'nota_credito' ? 'nota_credito' : 'reembolso_efectivo');
  }

  setBusquedaFactura(value: string): void {
    this.busquedaFactura.set(value);
  }

  elegirFactura(item: Factura): void {
    this.loadingFactura.set(true);
    this.formError.set('');
    this.inventario.facturaDevolucion(item.id).subscribe({
      next: (factura) => {
        this.factura.set(factura);
        this.lineas.set(
          factura.items.map((linea) => ({
            ...linea,
            cantidad_devolver: linea.cantidad_disponible > 0 ? 0 : 0,
            id_producto_cambio: null,
            cantidad_cambio: 0,
            precio_cambio: linea.precio_venta || linea.precio_unitario,
          }))
        );
        this.loadingFactura.set(false);
      },
      error: (err) => {
        this.loadingFactura.set(false);
        this.formError.set(apiErrorMessage(err, 'No se pudo cargar la factura.'));
      },
    });
  }

  setCantidad(item: LineaDevolucion, value: string): void {
    const n = Math.min(item.cantidad_disponible, Math.max(0, Math.trunc(Number(value) || 0)));
    this.patchLinea(item, {
      cantidad_devolver: n,
      cantidad_cambio: this.esCambio() ? n || item.cantidad_cambio : item.cantidad_cambio,
    });
  }

  setCantidadCambio(item: LineaDevolucion, value: string): void {
    const n = Math.max(0, Math.trunc(Number(value) || 0));
    this.patchLinea(item, { cantidad_cambio: n });
  }

  setPrecioCambio(item: LineaDevolucion, value: string): void {
    const n = Math.max(0, Number(value) || 0);
    this.patchLinea(item, { precio_cambio: round(n) });
  }

  setProductoCambio(item: LineaDevolucion, value: string): void {
    const id = Number(value) || null;
    this.patchLinea(item, {
      id_producto_cambio: id,
      cantidad_cambio: item.cantidad_cambio || item.cantidad_devolver || 1,
    });
  }

  guardar(): void {
    const factura = this.factura();
    const bodega = this.bodegaId();
    if (!this.puedeGuardar() || !factura || !bodega) {
      this.formError.set('Completa factura, bodega y cantidades a devolver.');
      return;
    }
    const items = this.lineas()
      .filter((item) => item.cantidad_devolver > 0)
      .map((item) => ({
        id_factura_item: item.id_factura_item,
        cantidad: item.cantidad_devolver,
        id_producto_cambio: this.esCambio() ? item.id_producto_cambio : null,
        cantidad_cambio: this.esCambio() ? item.cantidad_cambio : 0,
        precio_cambio: this.esCambio() ? item.precio_cambio : 0,
      }));
    this.saving.set(true);
    this.formError.set('');
    this.inventario
      .crearDevolucion({
        id_factura: factura.id,
        id_bodega: bodega,
        razon: this.razon(),
        resolucion: this.esCambio() ? 'cambio' : this.resolucion(),
        observacion: this.observacion().trim() || null,
        items,
      })
      .subscribe({
        next: () => {
          this.saving.set(false);
          this.formOpen.set(false);
          this.pagina.set(1);
        },
        error: (err) => {
          this.saving.set(false);
          this.formError.set(apiErrorMessage(err, 'No se pudo procesar la devolución.'));
        },
      });
  }

  ver(item: DevolucionInventario, event?: Event): void {
    event?.stopPropagation();
    this.menuId.set(null);
    this.detalle.set(item);
  }

  toggleMenu(id: number, event: Event): void {
    event.stopPropagation();
    this.menuId.update((current) => (current === id ? null : id));
  }

  setFiltroRazon(value: string): void {
    this.razonFiltro.set((value || '') as RazonDevolucion | '');
    this.pagina.set(1);
  }

  setBusqueda(value: string): void {
    this.busqueda.set(value);
    this.pagina.set(1);
  }

  setPageSize(value: string): void {
    this.pageSize.set(Number(value) || 10);
    this.pagina.set(1);
  }

  irPagina(n: PageToken): void {
    if (n === 'gap') {
      return;
    }
    this.pagina.set(clampPage(n, this.filtrados().length, this.pageSize()));
  }

  etiquetaRazon(value: RazonDevolucion): string {
    return RAZON_LABEL[value] || value;
  }

  etiquetaResolucion(value: ResolucionDevolucion): string {
    return RESOLUCION_LABEL[value] || value;
  }

  productosResumen(item: DevolucionInventario): string {
    return item.items.map((linea) => linea.producto).join(', ') || '—';
  }

  cantidadTotal(item: DevolucionInventario): number {
    return item.items.reduce((sum, linea) => sum + Number(linea.cantidad || 0), 0);
  }

  formatoFecha(value: string): string {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) {
      return value;
    }
    const pad = (n: number) => String(n).padStart(2, '0');
    let hours = date.getHours();
    const ampm = hours >= 12 ? 'pm' : 'am';
    hours = hours % 12 || 12;
    return `${pad(date.getDate())}-${pad(date.getMonth() + 1)}-${date.getFullYear()} ${pad(hours)}:${pad(
      date.getMinutes()
    )} ${ampm}`;
  }

  moneda(value: number): string {
    return `RD$ ${Number(value || 0).toLocaleString('es-DO', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`;
  }

  formatoCantidad(value: number): string {
    return Number(value || 0).toFixed(2);
  }

  impactoInventario(item: DevolucionInventario): string {
    if (item.razon === 'danado' || item.razon === 'vencido') {
      return 'No reingresa a stock vendible (merma / no apto).';
    }
    if (item.razon === 'cambio_producto') {
      return 'Entra el producto devuelto y sale el producto entregado.';
    }
    return 'Reingresa a la bodega seleccionada.';
  }

  private patchLinea(item: LineaDevolucion, patch: Partial<LineaDevolucion>): void {
    this.lineas.update((lista) =>
      lista.map((row) => (row.id_factura_item === item.id_factura_item ? { ...row, ...patch } : row))
    );
  }

  private cargarCatalogo(idBodega: number): void {
    this.loadingCatalogo.set(true);
    this.inventario.listarExistencias(idBodega).subscribe({
      next: (rows) => {
        this.catalogo.set(rows);
        this.loadingCatalogo.set(false);
      },
      error: (err) => {
        this.loadingCatalogo.set(false);
        this.formError.set(apiErrorMessage(err, 'No se pudieron cargar los productos de la bodega.'));
      },
    });
  }
}

function round(value: number): number {
  return Math.round(Number(value || 0) * 100) / 100;
}

import { Component, HostListener, OnInit, computed, signal } from '@angular/core';
import { DecimalPipe } from '@angular/common';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { forkJoin } from 'rxjs';
import { InventarioService } from '../../core/services/inventario.service';
import { Producto, ProductoPayload, TipoArticulo } from '../../core/models/inventario.model';
import { apiErrorMessage } from '../../core/utils/api-error';
import { clampPage, compactPages, pageRange, pageSlice, PageToken } from '../../core/utils/paginate';
import { UiIcon } from '../../shared/ui-icon/ui-icon';
import { RowMenu } from '../../shared/row-menu/row-menu';
import { InventarioNav } from './inventario-nav';

const UNIDADES_MEDIDA = [
  'unidad',
  'pieza',
  'unidad de servicio',
  'kilogramo',
  'gramo',
  'metro',
  'pulgada',
  'pie',
  'yarda',
  'millar',
  'centimetro',
  'galon',
  'caja',
  'kit',
  'bloque',
  'libra',
  'fardo',
  'onza',
  'docena',
];

const TIPOS_IMPUESTO = [
  { id: 'iva', nombre: 'Impuesto al Valor Agregado' },
  { id: 'idp', nombre: 'Impuesto sobre Derivados del Petróleo' },
  { id: 'turismo', nombre: 'Impuesto de Turismo - Hospedaje' },
  { id: 'timbre', nombre: 'Timbre' },
];

const IMPUESTOS = [
  { tipo: 'iva', nombre: 'IVA 12%', descripcion: 'Impuesto al valor agregado', porcentaje: 12 },
  { tipo: 'iva', nombre: 'Exento 0%', descripcion: 'Exento de IVA', porcentaje: 0 },
  { tipo: 'idp', nombre: 'IDP', descripcion: 'Impuesto sobre derivados del petróleo', porcentaje: 0 },
  { tipo: 'turismo', nombre: 'Turismo 10%', descripcion: 'Impuesto de turismo - hospedaje', porcentaje: 10 },
  { tipo: 'timbre', nombre: 'Timbre', descripcion: 'Timbre fiscal', porcentaje: 0 },
];

@Component({
  selector: 'app-productos',
  imports: [DecimalPipe, ReactiveFormsModule, UiIcon, RowMenu, InventarioNav],
  templateUrl: './productos.html',
  styleUrls: ['./inventario-shared.css', './productos.css'],
})
export class Productos implements OnInit {
  readonly busqueda = signal('');
  readonly filtroEstado = signal('activo');
  readonly filtroBodega = signal('');
  readonly filtroCategoria = signal('');
  readonly filtroSubcategoria = signal('');
  readonly filtroMarca = signal('');
  readonly categoriaForm = signal('');
  readonly subcategoriaForm = signal('');
  readonly marcaForm = signal('');
  readonly filtroProveedor = signal('');
  readonly filtroCantidad = signal('');
  readonly filtrosOpen = signal(false);
  readonly pagina = signal(1);
  readonly pageSize = signal(10);
  readonly loading = signal(false);
  readonly saving = signal(false);
  readonly errorMessage = signal('');
  readonly formOpen = signal(false);
  readonly editingId = signal<number | null>(null);
  readonly unidades = UNIDADES_MEDIDA;
  readonly tiposImpuesto = TIPOS_IMPUESTO;
  readonly listasPrecio = ['P1', 'P2', 'P3'] as const;

  readonly categoriasFiltro = computed(() =>
    this.inventario
      .categorias()
      .filter((c) => c.estado)
      .map((c) => c.nombre)
  );

  readonly subcategoriasFiltro = computed(() => {
    const categoria = this.filtroCategoria();
    return this.inventario
      .subcategorias()
      .filter((item) => item.estado && (!categoria || item.categoria === categoria))
      .map((item) => item.nombre);
  });

  readonly marcasFiltro = computed(() =>
    this.inventario
      .marcas()
      .filter((item) => item.estado)
      .map((item) => item.nombre)
  );

  readonly categoriasFormulario = computed(() => {
    const actual = this.categoriaForm();
    return this.inventario
      .categorias()
      .filter((item) => item.estado || item.nombre === actual)
      .map((item) => item.nombre);
  });

  readonly subcategoriasFormulario = computed(() => {
    const categoria = this.categoriaForm();
    const actual = this.subcategoriaForm();
    return this.inventario
      .subcategorias()
      .filter(
        (item) =>
          item.categoria === categoria && (item.estado || item.nombre === actual)
      )
      .map((item) => item.nombre);
  });

  readonly marcasFormulario = computed(() => {
    const actual = this.marcaForm();
    return this.inventario
      .marcas()
      .filter((item) => item.estado || item.nombre === actual)
      .map((item) => item.nombre);
  });

  readonly bodegasFiltro = computed(() =>
    this.inventario
      .almacenes()
      .filter((item) => item.estado)
      .map((item) => item.nombre)
  );

  impuestosOpciones() {
    const tipo = this.form.controls.impuesto_tipo.value;
    return IMPUESTOS.filter((item) => !tipo || item.tipo === tipo);
  }

  readonly filtrados = computed(() => {
    const q = this.busqueda().trim().toLowerCase();
    const estado = this.filtroEstado();
    const bodega = this.filtroBodega();
    const categoria = this.filtroCategoria();
    const subcategoria = this.filtroSubcategoria();
    const marca = this.filtroMarca();
    const proveedor = this.filtroProveedor();
    const cantidad = this.filtroCantidad();
    return this.inventario.productos().filter((p) => {
      const matchQ =
        !q ||
        p.nombre.toLowerCase().includes(q) ||
        p.sku.toLowerCase().includes(q) ||
        (p.categoria || '').toLowerCase().includes(q) ||
        (p.marca || '').toLowerCase().includes(q);
      const matchEstado = !estado || (estado === 'activo' ? p.estado : !p.estado);
      const matchBodega = !bodega || (p.bodega || '') === bodega;
      const matchCategoria = !categoria || (p.categoria || '') === categoria;
      const matchSub = !subcategoria || (p.subcategoria || '') === subcategoria;
      const matchMarca = !marca || (p.marca || '') === marca;
      const matchProveedor = !proveedor || String(p.id_proveedor || '') === proveedor;
      const matchCantidad =
        !cantidad ||
        (cantidad === 'bajo_minimo' && p.stock_actual <= p.stock_minimo) ||
        (cantidad === 'sin_stock' && p.stock_actual <= 0) ||
        (cantidad === 'con_stock' && p.stock_actual > 0);
      return (
        matchQ &&
        matchEstado &&
        matchBodega &&
        matchCategoria &&
        matchSub &&
        matchMarca &&
        matchProveedor &&
        matchCantidad
      );
    });
  });

  readonly visibles = computed(() => pageSlice(this.filtrados(), this.pagina(), this.pageSize()));
  readonly paginas = computed(() => compactPages(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly rango = computed(() => pageRange(this.filtrados().length, this.pagina(), this.pageSize()));
  readonly paginaActual = computed(() => clampPage(this.pagina(), this.filtrados().length, this.pageSize()));
  readonly totalPaginas = computed(() =>
    Math.max(1, Math.ceil(Math.max(this.filtrados().length, 0) / this.pageSize()))
  );
  readonly montoInventario = computed(() =>
    this.filtrados().reduce((total, item) => total + this.valorCosto(item), 0)
  );

  readonly form;

  constructor(
    readonly inventario: InventarioService,
    private readonly fb: FormBuilder
  ) {
    this.form = this.fb.group({
      tipo: this.fb.nonNullable.control<TipoArticulo>('producto', Validators.required),
      sku: ['', Validators.required],
      nombre: ['', Validators.required],
      unidad_medida: ['unidad', Validators.required],
      detalle: [''],
      ubicacion: [''],
      impuesto_tipo: ['iva'],
      impuesto_nombre: ['IVA 12%'],
      impuesto_porcentaje: [12],
      costo_compra: [0, [Validators.required, Validators.min(0)]],
      stock_minimo: [0, [Validators.required, Validators.min(0)]],
      stock_reorden: [0],
      stock_maximo: [0],
      precio_venta: [0, [Validators.required, Validators.min(0)]],
      precio_2: [0],
      precio_3: [0],
      categoria: [''],
      subcategoria: [''],
      marca: [''],
      unidad_compra: ['unidad'],
      factor_conversion: [1],
      es_padre_variantes: [false],
      bodega: [''],
      stock_actual: [0, [Validators.required, Validators.min(0)]],
      id_proveedor: [null as number | null],
      estado: [true],
    });

    this.form.controls.categoria.valueChanges.subscribe((value) => {
      this.categoriaForm.set(value || '');
      const sub = this.form.controls.subcategoria.value || '';
      const pertenece = this.inventario
        .subcategorias()
        .some((item) => item.categoria === value && item.nombre === sub);
      if (sub && !pertenece) {
        this.form.controls.subcategoria.setValue('');
      }
    });
    this.form.controls.subcategoria.valueChanges.subscribe((value) => this.subcategoriaForm.set(value || ''));
    this.form.controls.marca.valueChanges.subscribe((value) => this.marcaForm.set(value || ''));

    this.form.controls.impuesto_tipo.valueChanges.subscribe((tipo) => {
      const opciones = IMPUESTOS.filter((item) => item.tipo === tipo);
      const actual = this.form.controls.impuesto_nombre.value;
      if (!opciones.some((item) => item.nombre === actual)) {
        this.aplicarImpuesto(opciones[0]?.nombre || 'IVA 12%');
      }
    });
  }

  ngOnInit(): void {
    this.cargar();
  }

  @HostListener('document:keydown.escape')
  onEscape(): void {
    if (this.formOpen() && !this.saving()) {
      this.cancelar();
    }
  }

  cargar(): void {
    this.loading.set(true);
    this.errorMessage.set('');
    forkJoin({
      proveedores: this.inventario.listarProveedores(),
      productos: this.inventario.listarProductos(),
      categorias: this.inventario.listarCategorias(),
      subcategorias: this.inventario.listarSubcategorias(),
      marcas: this.inventario.listarMarcas(),
      bodegas: this.inventario.listarBodegas(),
    }).subscribe({
      next: () => this.loading.set(false),
      error: (err) => {
        this.loading.set(false);
        this.errorMessage.set(apiErrorMessage(err, 'No se pudieron cargar los productos.'));
      },
    });
  }

  defaults() {
    return {
      tipo: 'producto' as TipoArticulo,
      sku: '',
      nombre: '',
      unidad_medida: 'unidad',
      detalle: '',
      ubicacion: '',
      impuesto_tipo: 'iva',
      impuesto_nombre: 'IVA 12%',
      impuesto_porcentaje: 12,
      costo_compra: 0,
      stock_minimo: 0,
      stock_reorden: 0,
      stock_maximo: 0,
      precio_venta: 0,
      precio_2: 0,
      precio_3: 0,
      categoria: '',
      subcategoria: '',
      marca: '',
      unidad_compra: 'unidad',
      factor_conversion: 1,
      es_padre_variantes: false,
      bodega: '',
      stock_actual: 0,
      id_proveedor: null as number | null,
      estado: true,
    };
  }

  abrirNuevo(): void {
    this.editingId.set(null);
    this.form.reset(this.defaults());
    this.errorMessage.set('');
    this.formOpen.set(true);
  }

  abrirEditar(item: Producto): void {
    this.editingId.set(item.id);
    this.form.reset({
      tipo: this.esServicio(item) ? 'servicio' : 'producto',
      sku: item.sku,
      nombre: item.nombre,
      unidad_medida: item.unidad_medida || 'unidad',
      detalle: item.detalle ?? '',
      ubicacion: item.ubicacion ?? '',
      impuesto_tipo: item.impuesto_tipo || 'iva',
      impuesto_nombre: item.impuesto_nombre || 'IVA 12%',
      impuesto_porcentaje: Number(item.impuesto_porcentaje ?? 12),
      costo_compra: Number(item.costo_compra),
      stock_minimo: item.stock_minimo,
      stock_reorden: item.stock_reorden ?? 0,
      stock_maximo: item.stock_maximo ?? 0,
      precio_venta: Number(item.precio_venta),
      precio_2: Number(item.precio_2 || 0),
      precio_3: Number(item.precio_3 || 0),
      categoria: item.categoria ?? '',
      subcategoria: item.subcategoria ?? '',
      marca: item.marca ?? '',
      unidad_compra: item.unidad_compra || item.unidad_medida || 'unidad',
      factor_conversion: Number(item.factor_conversion || 1),
      es_padre_variantes: !!item.es_padre_variantes,
      bodega: item.bodega ?? '',
      stock_actual: item.stock_actual,
      id_proveedor: item.id_proveedor,
      estado: !!item.estado,
    });
    this.errorMessage.set('');
    this.formOpen.set(true);
  }

  cancelar(): void {
    this.formOpen.set(false);
    this.editingId.set(null);
  }

  guardar(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      this.errorMessage.set('Completa código, nombre, unidad, costo y precios.');
      return;
    }

    const value = this.form.getRawValue();
    const payload: ProductoPayload = {
      sku: String(value.sku).trim(),
      nombre: String(value.nombre).trim(),
      tipo: value.tipo,
      detalle: value.detalle?.trim() || null,
      ubicacion: value.ubicacion?.trim() || null,
      unidad_medida: value.unidad_medida,
      categoria: value.categoria?.trim() || null,
      subcategoria: value.subcategoria?.trim() || null,
      marca: value.marca?.trim() || null,
      impuesto_tipo: value.impuesto_tipo || null,
      impuesto_nombre: value.impuesto_nombre || null,
      impuesto_porcentaje: Number(value.impuesto_porcentaje),
      precio_venta: Number(value.precio_venta),
      precio_2: Number(value.precio_2),
      precio_3: Number(value.precio_3),
      costo_compra: Number(value.costo_compra),
      stock_actual: Number(value.stock_actual),
      stock_minimo: Number(value.stock_minimo),
      stock_reorden: Number(value.stock_reorden),
      stock_maximo: Number(value.stock_maximo),
      unidad_compra: value.unidad_compra || null,
      factor_conversion: Number(value.factor_conversion || 1),
      es_padre_variantes: !!value.es_padre_variantes,
      bodega: value.bodega?.trim() || null,
      id_proveedor: value.id_proveedor ? Number(value.id_proveedor) : null,
      estado: !!value.estado,
    };

    this.saving.set(true);
    this.errorMessage.set('');

    const request = this.editingId()
      ? this.inventario.actualizarProducto(this.editingId()!, payload)
      : this.inventario.crearProducto(payload);

    request.subscribe({
      next: () => {
        this.saving.set(false);
        this.formOpen.set(false);
        this.editingId.set(null);
      },
      error: (err) => {
        this.saving.set(false);
        this.errorMessage.set(apiErrorMessage(err));
      },
    });
  }

  desactivar(item: Producto): void {
    if (!item.estado) {
      return;
    }
    this.saving.set(true);
    this.errorMessage.set('');
    this.inventario.desactivarProducto(item.id).subscribe({
      next: () => this.saving.set(false),
      error: (err) => {
        this.saving.set(false);
        this.errorMessage.set(apiErrorMessage(err));
      },
    });
  }

  aplicarImpuesto(nombre: string): void {
    const impuesto = IMPUESTOS.find((item) => item.nombre === nombre);
    if (!impuesto) {
      return;
    }
    this.form.patchValue({
      impuesto_tipo: impuesto.tipo,
      impuesto_nombre: impuesto.nombre,
      impuesto_porcentaje: impuesto.porcentaje,
    });
  }

  impuestoAplicado() {
    const nombre = this.form.controls.impuesto_nombre.value;
    const porcentaje = Number(this.form.controls.impuesto_porcentaje.value || 0);
    const found = IMPUESTOS.find((item) => item.nombre === nombre);
    return {
      nombre: nombre || 'IVA 12%',
      descripcion: found?.descripcion || 'Impuesto al valor agregado',
      porcentaje,
    };
  }

  tasa(): number {
    return Number(this.form.controls.impuesto_porcentaje.value || 0) / 100;
  }

  precioCon(lista: 'P1' | 'P2' | 'P3'): number {
    if (lista === 'P2') {
      return Number(this.form.controls.precio_2.value || 0);
    }
    if (lista === 'P3') {
      return Number(this.form.controls.precio_3.value || 0);
    }
    return Number(this.form.controls.precio_venta.value || 0);
  }

  precioSin(lista: 'P1' | 'P2' | 'P3'): number {
    const tasa = this.tasa();
    const con = this.precioCon(lista);
    return tasa > 0 ? con / (1 + tasa) : con;
  }

  setPrecioCon(lista: 'P1' | 'P2' | 'P3', value: string): void {
    const n = Math.max(0, Number(value) || 0);
    if (lista === 'P2') {
      this.form.controls.precio_2.setValue(n);
    } else if (lista === 'P3') {
      this.form.controls.precio_3.setValue(n);
    } else {
      this.form.controls.precio_venta.setValue(n);
    }
  }

  setPrecioSin(lista: 'P1' | 'P2' | 'P3', value: string): void {
    const n = Math.max(0, Number(value) || 0);
    const con = n * (1 + this.tasa());
    this.setPrecioCon(lista, String(con));
  }

  utilidadMonto(lista: 'P1' | 'P2' | 'P3'): number {
    return this.precioSin(lista) - Number(this.form.controls.costo_compra.value || 0);
  }

  utilidadPct(lista: 'P1' | 'P2' | 'P3'): number {
    const costo = Number(this.form.controls.costo_compra.value || 0);
    if (costo <= 0) {
      return 0;
    }
    return (this.utilidadMonto(lista) / costo) * 100;
  }

  setBusqueda(value: string): void {
    this.busqueda.set(value);
    this.pagina.set(1);
  }

  setFiltroCategoria(value: string): void {
    this.filtroCategoria.set(value);
    this.filtroSubcategoria.set('');
    this.pagina.set(1);
  }

  setFiltroEstado(value: string): void {
    this.filtroEstado.set(value);
    this.pagina.set(1);
  }

  setPageSize(value: string): void {
    this.pageSize.set(Number(value) || 10);
    this.pagina.set(1);
  }

  irPagina(n: PageToken): void {
    if (n === 'gap') {
      return;
    }
    this.pagina.set(clampPage(n, this.filtrados().length, this.pageSize()));
  }

  toggleFiltros(): void {
    this.filtrosOpen.update((value) => !value);
  }

  invalid(name: string): boolean {
    const control = this.form.get(name);
    return !!control && control.invalid && (control.touched || control.dirty);
  }

  requiredError(name: string): boolean {
    const control = this.form.get(name);
    return !!control && control.hasError('required') && (control.touched || control.dirty);
  }

  valorCosto(item: Producto): number {
    return Number(item.costo_compra || 0) * Number(item.stock_actual || 0);
  }

  tipo(item: Producto): string {
    return this.esServicio(item) ? 'Servicio' : 'Producto';
  }

  esServicio(item: Producto): boolean {
    return item.tipo === 'servicio' || String(item.categoria || '').toLowerCase().includes('servicio');
  }

  gravamen(item: Producto): string {
    return Number(item.impuesto_porcentaje ?? 12) > 0 ? 'Gravado' : 'Exento';
  }

  unidad(item: Producto): string {
    const unidad = item.unidad_medida || 'unidad';
    return unidad.charAt(0).toUpperCase() + unidad.slice(1);
  }

  precioLista(item: Producto, lista: 1 | 2 | 3): number {
    if (lista === 2) {
      return Number(item.precio_2 || 0);
    }
    if (lista === 3) {
      return Number(item.precio_3 || 0);
    }
    return Number(item.precio_venta || 0);
  }

  iniciales(nombre: string): string {
    return nombre
      .split(' ')
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0])
      .join('')
      .toUpperCase();
  }

  sinImpuesto(precio: number | string, porcentaje: number | string | undefined): number {
    const tasa = Number(porcentaje ?? 12) / 100;
    const n = Number(precio || 0);
    return tasa > 0 ? n / (1 + tasa) : n;
  }

  tituloModal(): string {
    const tipo = this.form.controls.tipo.value === 'servicio' ? 'Servicio' : 'Producto';
    return this.editingId() ? `Editar ${tipo}` : `Nuevo ${tipo}`;
  }
}

import { Component, signal } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';

@Component({
  selector: 'app-login',
  imports: [ReactiveFormsModule],
  templateUrl: './login.html',
  styleUrl: './login.css',
})
export class Login {
  readonly loading = signal(false);
  readonly errorMessage = signal('');

  readonly form;

  constructor(
    private readonly fb: FormBuilder,
    private readonly auth: AuthService,
    private readonly router: Router
  ) {
    this.form = this.fb.nonNullable.group({
      email: ['admin@demo.com', [Validators.required, Validators.email]],
      password: ['Admin123!', [Validators.required, Validators.minLength(6)]],
    });
  }

  onSubmit(): void {
    this.errorMessage.set('');

    if (this.form.invalid) {
      this.form.markAllAsTouched();
      this.errorMessage.set('Completa email y contraseña válidos.');
      return;
    }

    this.loading.set(true);
    const { email, password } = this.form.getRawValue();

    this.auth.login(email, password).subscribe({
      next: () => {
        this.loading.set(false);
        void this.router.navigate(['/dashboard']);
      },
      error: (err) => {
        this.loading.set(false);
        const message = err?.error?.message || 'No se pudo iniciar sesión.';
        this.errorMessage.set(message);
      },
    });
  }
}
